function design(site, analyse) {
  const CALL_LIMIT = 390;
  let calls = 0;

  const xs = [
    0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3,
    22.057, 24.814, 27.571, 30.329, 33.086, 35.843, 38.6
  ];

  // Options are ordered approximately by increasing area.
  const options = {
    bottomFar: [
      "CHS88.9x5", "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
      "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS244.5x8", "CHS273x10"
    ],
    bottomLow: [
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
      "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8",
      "CHS244.5x8", "CHS273x10", "CHS323.9x10"
    ],
    topFar: [
      "CHS88.9x5", "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
      "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS244.5x8", "CHS273x10"
    ],
    topTransition: [
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
      "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8",
      "CHS244.5x8", "CHS273x10", "CHS323.9x10"
    ],
    topLow: [
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
      "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8",
      "CHS244.5x8", "CHS273x10", "CHS323.9x10"
    ],
    verticalFar: [
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
      "CHS193.7x6.3", "CHS219.1x8", "CHS244.5x8"
    ],
    verticalLow: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5"
    ],
    diagFar: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
      "CHS168.3x6.3", "CHS193.7x6.3", "CHS219.1x8"
    ],
    diagTransition: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
      "CHS193.7x6.3"
    ],
    diagLow: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
      "CHS114.3x5", "CHS139.7x5", "CHS168.3x5"
    ],
    supportLeg: [
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
      "CHS193.7x6.3", "CHS219.1x8"
    ],
    supportBrace: [
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
      "CHS193.7x6.3", "CHS219.1x8", "CHS244.5x8"
    ]
  };

  const meta = [];
  const add = (a, b, group) => meta.push({ a, b, group });

  for (let i = 0; i < 14; i++) {
    add(
      "D" + i,
      "D" + (i + 1),
      i >= 9 && i <= 11 ? "bottomLow" : "bottomFar"
    );
  }

  for (let i = 0; i < 14; i++) {
    const group =
      i === 8 || i === 12 ? "topTransition" :
      i >= 9 && i <= 11 ? "topLow" : "topFar";
    add("T" + i, "T" + (i + 1), group);
  }

  for (let i = 0; i < 15; i++) {
    add(
      "D" + i,
      "T" + i,
      i >= 9 && i <= 12 ? "verticalLow" : "verticalFar"
    );
  }

  for (let i = 0; i < 14; i++) {
    const group =
      i === 8 || i === 12 ? "diagTransition" :
      i >= 9 && i <= 11 ? "diagLow" : "diagFar";

    // Pratt diagonals slope toward the centre of the span.
    if (i <= 6) add("T" + i, "D" + (i + 1), group);
    else add("D" + i, "T" + (i + 1), group);
  }

  // The diagonal anchors the offset pinned support; the end posts
  // connect the deck ends to the two specified support nodes.
  add("S1", "D0", "supportLeg");
  add("D14", "S2", "supportLeg");
  add("S1", "D1", "supportBrace");

  const byGroup = {};
  for (let i = 0; i < meta.length; i++) {
    const g = meta[i].group;
    if (!byGroup[g]) byGroup[g] = [];
    byGroup[g].push(i);
  }

  const note =
    "A pinned S460 Pratt truss keeps the upper chord below the building clearance and braces the offset pin support.";

  function build(h, ranks) {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({
        id: "T" + i,
        x: xs[i],
        y: i >= 9 && i <= 12 ? 2.1 : h,
        joint: "pin"
      });
    }

    const members = meta.map((m, i) => [
      m.a,
      m.b,
      "S460 " + options[m.group][ranks[i]]
    ]);

    return { note, nodes, members };
  }

  function num(v) {
    if (typeof v === "number" && Number.isFinite(v)) return v;
    if (typeof v === "string" && v.trim() !== "") {
      const x = Number(v);
      if (Number.isFinite(x)) return x;
    }
    return NaN;
  }

  function normUtil(v) {
    let x = num(v);
    if (!Number.isFinite(x)) return NaN;
    if (x > 2 && x <= 100) x /= 100;
    return x;
  }

  function utilOf(r) {
    let u = normUtil(r.maxUtil);
    if (Array.isArray(r.members)) {
      for (const m of r.members) {
        const v = normUtil(m && m.util);
        if (Number.isFinite(v) && (!Number.isFinite(u) || v > u)) u = v;
      }
    }
    return u;
  }

  function fatigueUse(r) {
    const f = r.fatigueWorst;
    const direct = num(f);
    if (Number.isFinite(direct)) {
      const v = Math.abs(direct);
      return v > 2 ? v / 90 : v;
    }

    if (f && typeof f === "object") {
      for (const key of ["util", "utilization", "ratio", "usage"]) {
        const u = normUtil(f[key]);
        if (Number.isFinite(u)) return u;
      }

      let range = NaN;
      for (const key of ["range", "stressRange", "deltaSigma", "stress", "value"]) {
        range = num(f[key]);
        if (Number.isFinite(range)) break;
      }
      if (Number.isFinite(range)) {
        let limit = num(f.limit);
        if (!Number.isFinite(limit) || limit <= 0) limit = 90;
        return Math.abs(range) / limit;
      }
    }
    return NaN;
  }

  function robust(r) {
    if (!r || r.error || r.ok !== true) return false;

    const u = utilOf(r);
    if (Number.isFinite(u) && u > 0.68) return false;

    const sag = num(r.sag);
    let sagLimit = num(r.sagLimit);
    if (!Number.isFinite(sagLimit) || sagLimit <= 0) sagLimit = 0.1287;
    if (Number.isFinite(sag) && Math.abs(sag) / sagLimit > 0.72) return false;

    const f = num(r.frequency);
    let fMin = num(r.fMin);
    if (!Number.isFinite(fMin) || fMin <= 0) fMin = 2.5;
    if (Number.isFinite(f) && f < Math.max(fMin * 1.08, fMin + 0.15)) return false;

    const fatigue = fatigueUse(r);
    if (Number.isFinite(fatigue) && fatigue > 0.72) return false;

    return true;
  }

  let bestSafe = null;
  let bestPassing = null;
  let leastBad = null;

  function remember(d, r, h, ranks) {
    if (!r || r.error) return;

    let mass = num(r.mass);
    if (!Number.isFinite(mass)) {
      const score = num(r.score);
      mass = Number.isFinite(score) && score > 0
        ? 18623 * 100 / score
        : Infinity;
    }

    const record = { design: d, result: r, h, ranks: ranks.slice(), mass };

    if (r.ok === true) {
      if (!bestPassing || mass < bestPassing.mass) bestPassing = record;
      if (robust(r) && (!bestSafe || mass < bestSafe.mass)) bestSafe = record;
    } else {
      const u = utilOf(r);
      const badness = Number.isFinite(u) ? u : Infinity;
      if (!leastBad || badness < leastBad.badness) {
        record.badness = badness;
        leastBad = record;
      }
    }
  }

  function run(d) {
    if (calls >= CALL_LIMIT) return null;
    calls++;
    try {
      return analyse(d);
    } catch (e) {
      return { error: String(e) };
    }
  }

  const reduceOrder = [
    "verticalLow", "diagLow", "supportLeg", "supportBrace",
    "diagTransition", "verticalFar", "diagFar", "topTransition",
    "topLow", "topFar", "bottomLow", "bottomFar"
  ];

  for (const h of [4.6, 5.5, 6.3]) {
    if (calls >= CALL_LIMIT) break;

    let ranks = meta.map(m => options[m.group].length - 1);
    const initial = build(h, ranks);
    const initialResult = run(initial);
    remember(initial, initialResult, h, ranks);

    if (!robust(initialResult)) continue;

    for (const group of reduceOrder) {
      const ids = byGroup[group] || [];
      if (ids.length === 0) continue;

      while (calls < CALL_LIMIT && ranks[ids[0]] > 0) {
        const trialRanks = ranks.slice();
        for (const j of ids) trialRanks[j] = ranks[j] - 1;

        const trial = build(h, trialRanks);
        const result = run(trial);
        remember(trial, result, h, trialRanks);

        if (robust(result)) ranks = trialRanks;
        else break;
      }
    }
  }

  // Fine-tune individual members after the group sizing search.
  if (bestSafe) {
    const h = bestSafe.h;
    let ranks = bestSafe.ranks.slice();

    for (let pass = 0; pass < 3 && calls < CALL_LIMIT; pass++) {
      let changed = false;
      const start = pass === 0 ? 0 : (pass === 1 ? Math.floor(meta.length / 2) : Math.floor(meta.length / 4));

      for (let k = 0; k < meta.length && calls < CALL_LIMIT; k++) {
        const j = (start + k) % meta.length;
        if (ranks[j] <= 0) continue;

        const trialRanks = ranks.slice();
        trialRanks[j]--;
        const trial = build(h, trialRanks);
        const result = run(trial);
        remember(trial, result, h, trialRanks);

        if (robust(result)) {
          ranks = trialRanks;
          changed = true;
        }
      }

      if (!changed) break;
    }
  }

  if (bestSafe) return bestSafe.design;
  if (bestPassing) return bestPassing.design;
  if (leastBad) return leastBad.design;

  const fallbackRanks = meta.map(m => options[m.group].length - 1);
  return build(5.5, fallbackRanks);
}

function design(site, analyse) {
  const CALL_LIMIT = 390;
  let calls = 0;

  const xs = [
    0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3,
    22.057, 24.814, 27.571, 30.329, 33.086, 35.843, 38.6
  ];

  const chordSections = [
    "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
    "CHS139.7x5", "CHS168.3x5", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8",
    "CHS244.5x8", "CHS273x10", "CHS323.9x10",
    "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];

  const webSections = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2",
    "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
    "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
    "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8",
    "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5"
  ];

  const supportSections = [
    "CHS60.3x4", "CHS76.1x4", "CHS88.9x5",
    "CHS114.3x5", "CHS139.7x5", "CHS168.3x5",
    "CHS168.3x6.3", "CHS193.7x6.3", "CHS193.7x8",
    "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5",
    "CHS457x16"
  ];

  const options = {
    bottomFar: chordSections,
    bottomLow: chordSections,
    topFar: chordSections,
    topTransition: chordSections,
    topLow: chordSections,
    verticalFar: webSections,
    verticalLow: webSections,
    diagFar: webSections,
    diagTransition: webSections,
    diagLow: webSections,
    supportLeg: supportSections,
    supportBraceLeft: supportSections,
    supportBraceRight: supportSections
  };

  const meta = [];
  const add = (a, b, group) => meta.push({ a, b, group });

  // Deck and upper chords.
  for (let i = 0; i < 14; i++) {
    add("D" + i, "D" + (i + 1),
      i >= 9 && i <= 11 ? "bottomLow" : "bottomFar");
  }

  for (let i = 0; i < 14; i++) {
    const group =
      i === 8 || i === 12 ? "topTransition" :
      i >= 9 && i <= 11 ? "topLow" : "topFar";
    add("T" + i, "T" + (i + 1), group);
  }

  // Posts.
  for (let i = 0; i < 15; i++) {
    add("D" + i, "T" + i,
      i >= 9 && i <= 12 ? "verticalLow" : "verticalFar");
  }

  // Pratt diagonals, meeting at the lower middle joint.
  for (let i = 0; i < 14; i++) {
    const group =
      i === 8 || i === 12 ? "diagTransition" :
      i >= 9 && i <= 11 ? "diagLow" : "diagFar";

    if (i <= 6) add("T" + i, "D" + (i + 1), group);
    else add("D" + i, "T" + (i + 1), group);
  }

  // Triangulated offset support connections at both ends.
  add("S1", "D0", "supportLeg");
  add("D14", "S2", "supportLeg");
  add("S1", "D1", "supportBraceLeft");
  add("D13", "S2", "supportBraceRight");

  const byGroup = {};
  for (let i = 0; i < meta.length; i++) {
    const group = meta[i].group;
    if (!byGroup[group]) byGroup[group] = [];
    byGroup[group].push(i);
  }

  const groupOrder = [
    "verticalLow", "diagLow", "diagTransition", "verticalFar",
    "diagFar", "supportBraceLeft", "supportBraceRight", "supportLeg",
    "topTransition", "topLow", "topFar", "bottomLow", "bottomFar"
  ];

  const note =
    "A fully triangulated pinned Pratt truss uses a second brace at the roller support, with sections reduced only while analysis checks retain margin.";

  function build(h, ranks) {
    const nodes = xs.map((x, i) => ({
      id: "T" + i,
      x,
      y: i >= 9 && i <= 12 ? 2.25 : h,
      joint: "pin"
    }));

    const members = meta.map((m, i) => [
      m.a,
      m.b,
      "S460 " + options[m.group][ranks[i]]
    ]);

    return { note, nodes, members };
  }

  function num(v) {
    if (typeof v === "number" && Number.isFinite(v)) return v;
    if (typeof v === "string" && v.trim() !== "") {
      const n = Number(v);
      if (Number.isFinite(n)) return n;
    }
    return NaN;
  }

  function normUtil(v) {
    let n = num(v);
    if (!Number.isFinite(n)) return NaN;
    if (n > 2 && n <= 500) n /= 100;
    return n;
  }

  function utilOf(r) {
    let u = normUtil(r && r.maxUtil);

    if (Array.isArray(r && r.members)) {
      for (const m of r.members) {
        const v = normUtil(m && m.util);
        if (Number.isFinite(v) && (!Number.isFinite(u) || v > u)) u = v;
      }
    }

    if (Array.isArray(r && r.cases)) {
      for (const c of r.cases) {
        const v = normUtil(c && c.maxUtil);
        if (Number.isFinite(v) && (!Number.isFinite(u) || v > u)) u = v;
      }
    }

    return u;
  }

  function fatigueUse(r) {
    const f = r && r.fatigueWorst;
    const direct = num(f);

    if (Number.isFinite(direct)) {
      return Math.abs(direct) > 2 ? Math.abs(direct) / 90 : Math.abs(direct);
    }

    if (f && typeof f === "object") {
      for (const key of ["util", "utilization", "ratio", "usage"]) {
        const u = normUtil(f[key]);
        if (Number.isFinite(u)) return u;
      }

      let range = NaN;
      for (const key of ["range", "stressRange", "deltaSigma", "stress", "value"]) {
        range = num(f[key]);
        if (Number.isFinite(range)) break;
      }

      if (Number.isFinite(range)) {
        let limit = num(f.limit);
        if (!Number.isFinite(limit) || limit <= 0) limit = 90;
        return Math.abs(range) / limit;
      }
    }

    return NaN;
  }

  function robust(r) {
    if (!r || r.error || r.ok !== true) return false;

    const u = utilOf(r);
    if (Number.isFinite(u) && u > 0.58) return false;

    let sag = Math.abs(num(r.sag));
    let sagLimit = num(r.sagLimit);
    if (!Number.isFinite(sagLimit) || sagLimit <= 0) sagLimit = 0.1287;

    if (Number.isFinite(sag)) {
      if (sag > 1 && sagLimit < 1) sag /= 1000;
      else if (sag < 1 && sagLimit > 1) sag *= 1000;
      if (sag / sagLimit > 0.70) return false;
    }

    const f = num(r.frequency);
    let fMin = num(r.fMin);
    if (!Number.isFinite(fMin) || fMin <= 0) fMin = 2.5;
    if (Number.isFinite(f) && f < Math.max(fMin + 0.25, fMin * 1.10)) {
      return false;
    }

    const fatigue = fatigueUse(r);
    if (Number.isFinite(fatigue) && fatigue > 0.68) return false;

    return true;
  }

  let bestSafe = null;
  let bestPassing = null;
  let leastBad = null;

  function assess(h, ranks) {
    if (calls >= CALL_LIMIT) return null;

    const design = build(h, ranks);
    let r;
    calls++;

    try {
      r = analyse(design);
    } catch (e) {
      r = { error: String(e) };
    }

    if (!r || r.error) return { design, result: r, safe: false };

    let mass = num(r.mass);
    if (!Number.isFinite(mass)) {
      const score = num(r.score);
      mass = Number.isFinite(score) && score > 0
        ? 18623 * 100 / score
        : Infinity;
    }

    const safe = robust(r);
    const record = {
      design,
      result: r,
      h,
      ranks: ranks.slice(),
      mass
    };

    if (r.ok === true &&
        (!bestPassing || record.mass < bestPassing.mass)) {
      bestPassing = record;
    }

    if (safe && (!bestSafe || record.mass < bestSafe.mass)) {
      bestSafe = record;
    }

    if (r.ok !== true) {
      const u = utilOf(r);
      const badness = Number.isFinite(u) ? u : Infinity;
      if (!leastBad || badness < leastBad.badness) {
        record.badness = badness;
        leastBad = record;
      }
    }

    return { ...record, safe };
  }

  const heights = [4.6, 5.5, 6.3];

  for (const h of heights) {
    if (calls >= CALL_LIMIT) break;

    const startCall = calls;
    const localLimit = Math.min(CALL_LIMIT, startCall + 96);
    let ranks = meta.map(m => options[m.group].length - 1);

    const initial = assess(h, ranks);
    if (!initial || !initial.safe) continue;

    for (const group of groupOrder) {
      const ids = byGroup[group] || [];
      if (ids.length === 0) continue;

      while (calls < localLimit) {
        let canReduce = false;
        for (const j of ids) {
          if (ranks[j] > 0) {
            canReduce = true;
            break;
          }
        }
        if (!canReduce) break;

        const trial = ranks.slice();
        for (const j of ids) {
          if (trial[j] > 0) trial[j]--;
        }

        const result = assess(h, trial);
        if (!result || !result.safe) break;
        ranks = trial;
      }
    }
  }

  // Fine-tune individual members of the lightest robust candidate.
  if (bestSafe && calls < CALL_LIMIT) {
    const h = bestSafe.h;
    let ranks = bestSafe.ranks.slice();
    const individualOrder = [];

    for (const group of groupOrder) {
      for (const j of (byGroup[group] || [])) individualOrder.push(j);
    }

    for (let pass = 0; pass < 3 && calls < CALL_LIMIT; pass++) {
      let changed = false;

      for (const j of individualOrder) {
        while (calls < CALL_LIMIT && ranks[j] > 0) {
          const trial = ranks.slice();
          trial[j]--;

          const result = assess(h, trial);
          if (!result || !result.safe) break;

          ranks = trial;
          changed = true;
        }
      }

      if (!changed) break;
    }
  }

  if (bestSafe) return bestSafe.design;
  if (bestPassing) return bestPassing.design;
  if (leastBad) return leastBad.design;

  const fallbackRanks = meta.map(m => options[m.group].length - 1);
  return build(5.5, fallbackRanks);
}

function design(site, analyse) {
  const CALL_LIMIT = 380;
  const UTIL_LIMIT = 0.62;
  const FATIGUE_LIMIT = 0.65;
  let calls = 0;

  const deckX = [
    0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3,
    22.057, 24.814, 27.571, 30.329, 33.086, 35.843, 38.6
  ];

  // The extra upper nodes sit on the building-clearance boundary.
  const upperX = [
    0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3,
    22.057, 24.814, 27.29, 30.329, 32.88, 35.843, 38.6
  ];

  const chordSections = [
