        const u = normUtil(f[key]);
        if (Number.isFinite(u)) return u;
      }

      let range = NaN;
      for (const key of ["range", "stressRange", "deltaSigma", "stress", "value"]) {
        range = num(f[key]);
        if (Number.isFinite(range)) break;
      }

      if (Number.isFinite(range)) {
        let limit = num(f.limit);
        if (!Number.isFinite(limit) || limit <= 0) limit = 90;
        return Math.abs(range) / limit;
      }
    }

    return NaN;
  }

  function isSafe(r) {
    if (!r || r.error || r.ok !== true) return false;

    const u = utilOf(r);
    if (!Number.isFinite(u) || u > 0.62) return false;

    const s = sagRatio(r);
    if (!Number.isFinite(s) || s > 0.78) return false;

    const f = num(r.frequency);
    let fMin = num(r.fMin);
    if (!Number.isFinite(fMin) || fMin <= 0) fMin = 2.5;
    const fTarget = Math.max(2.70, fMin + 0.20, fMin * 1.08);
    if (!Number.isFinite(f) || f < fTarget) return false;

    const fatigue = fatigueUse(r);
    if (Number.isFinite(fatigue) && fatigue > 0.66) return false;

    return true;
  }

  function massOf(r) {
    let m = num(r && r.mass);
    if (Number.isFinite(m)) return m;

    const score = num(r && r.score);
    if (Number.isFinite(score) && score > 0) {
      return 18623 * 100 / score;
    }

    return Infinity;
  }

  let bestSafe = null;
  let bestPassing = null;

  function assess(ranks, materials, sections) {
    if (calls >= CALL_LIMIT) return null;

    const d = build(ranks, materials, sections);
    calls++;

    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }

    const record = {
      design: d,
      result: r,
      ranks: ranks.slice(),
      materials: materials.slice(),
      sections: sections.slice(),
      mass: massOf(r),
      safe: isSafe(r)
    };

    if (r && r.ok === true &&
        (!bestPassing || record.mass < bestPassing.mass)) {
      bestPassing = record;
    }

    if (record.safe &&
        (!bestSafe || record.mass < bestSafe.mass)) {
      bestSafe = record;
    }

    return record;
  }

  const seedRecord = assess(seedRanks, seedMaterials, seedSections);
  let current = seedRecord;

  // Retain the known passing layout as the starting point; if needed,
  // try modestly stronger versions before doing any reductions.
  if (!current || !current.safe) {
    const variants = [
      seedRanks.map(r => Math.min(23, r + 2)),
      seedRanks.map(() => 23)
    ];

    for (const ranks of variants) {
      if (calls >= CALL_LIMIT) break;
      const sections = ranks.map(r => chs[r]);
      const rec = assess(ranks, seedMaterials, sections);
      if (rec && rec.safe &&
          (!current || !current.safe || rec.mass < current.mass)) {
        current = rec;
      }
    }
  }

  if (bestSafe && (!current || !current.safe ||
      bestSafe.mass < current.mass)) {
    current = bestSafe;
  }

  if (current && current.safe) {
    const order = meta.map((m, i) => i);
    order.sort((ia, ib) => {
      const wa = chsArea[current.ranks[ia]] * memberLength(meta[ia]);
      const wb = chsArea[current.ranks[ib]] * memberLength(meta[ib]);
      return wb - wa;
    });

    const primaryLimit = CALL_LIMIT - 75;

    // Binary-search the minimum safe CHS size for each member.
    for (const i of order) {
      if (calls >= primaryLimit) break;
      if (current.materials[i] !== "S460" ||
          current.sections[i].indexOf("CHS") !== 0) {
        continue;
      }

      const oldRank = current.ranks[i];
      if (oldRank <= 0) continue;

      let low = -1;
      let high = oldRank;
      let highRecord = current;

      while (high - low > 1 && calls < primaryLimit) {
        const mid = Math.floor((low + high) / 2);
        const trialRanks = current.ranks.slice();
        const trialSections = current.sections.slice();
        trialRanks[i] = mid;
        trialSections[i] = chs[mid];

        const rec = assess(
          trialRanks,
          current.materials,
          trialSections
        );

        if (rec && rec.safe) {
          high = mid;
          highRecord = rec;
        } else {
          low = mid;
        }
      }

      if (highRecord !== current) current = highRecord;
    }

    // Later reductions can free a little reserve in earlier members.
    const secondaryLimit = CALL_LIMIT - 35;
    for (let pass = 0; pass < 2 && calls < secondaryLimit; pass++) {
      let changed = false;

      for (const i of order) {
        if (calls >= secondaryLimit) break;
        if (current.materials[i] === "WIRE" ||
            current.ranks[i] <= 0 ||
            current.sections[i].indexOf("CHS") !== 0) {
          continue;
        }

        const trialRanks = current.ranks.slice();
        const trialSections = current.sections.slice();
        trialRanks[i]--;
        trialSections[i] = chs[trialRanks[i]];

        const rec = assess(
          trialRanks,
          current.materials,
          trialSections
        );

        if (rec && rec.safe) {
          current = rec;
          changed = true;
        }
      }

      if (!changed) break;
    }

    function reportFor(record, index) {
      const arr = record && record.result && record.result.members;
      if (!Array.isArray(arr)) return null;

      const m = meta[index];
      const exact1 = m.a + "-" + m.b;
      const exact2 = m.b + "-" + m.a;

      for (const item of arr) {
        if (!item) continue;
        const id = String(item.id || "");
        if (id === exact1 || id === exact2) return item;

        const parts = id.split("-");
        if (parts.length === 2) {
          const pair = [parts[0], parts[1]].sort().join("|");
          const target = [m.a, m.b].sort().join("|");
          if (pair === target) return item;
        }
      }

      return null;
    }

    // Test high-strength steel only where the reported governing mode
    // is compression-related rather than fatigue.
    const s690Candidates = [];
    for (let i = 0; i < meta.length; i++) {
      if (current.materials[i] !== "S460" ||
          current.sections[i].indexOf("CHS") !== 0 ||
          current.ranks[i] < 5) {
        continue;
      }

      const rep = reportFor(current, i);
      if (!rep) continue;

      const mode = String(rep.mode || "").toLowerCase();
      const compression = num(rep.compression);
      const u = normUtil(rep.util);

      if (mode.indexOf("fatigue") >= 0) continue;

      const compressionMode =
        mode.indexOf("buckl") >= 0 ||
        mode.indexOf("compress") >= 0 ||
        mode.indexOf("interaction") >= 0 ||
        (Number.isFinite(compression) && compression > 0.5);

      if (!compressionMode || !Number.isFinite(u) || u < 0.30) continue;
      s690Candidates.push({ i, u });
    }

    s690Candidates.sort((a, b) => b.u - a.u);

    for (const item of s690Candidates) {
      if (calls >= CALL_LIMIT - 22) break;
      const i = item.i;

      const trialMaterials = current.materials.slice();
      trialMaterials[i] = "S690";

      let rec = assess(
        current.ranks,
        trialMaterials,
        current.sections
      );

      if (!rec || !rec.safe) continue;
      current = rec;

      for (let step = 0; step < 2 && calls < CALL_LIMIT - 22; step++) {
        if (current.ranks[i] <= 0) break;

        const trialRanks = current.ranks.slice();
        const trialSections = current.sections.slice();
        trialRanks[i]--;
        trialSections[i] = chs[trialRanks[i]];

        rec = assess(trialRanks, current.materials, trialSections);
        if (rec && rec.safe) current = rec;
        else break;
      }
    }

    // Replace a few clearly tension-only web members with checked wires.
    const wireCandidates = [];

    for (let i = 0; i < meta.length; i++) {
      if (meta[i].group !== "web" ||
          current.materials[i] !== "S460" ||
          current.sections[i].indexOf("CHS") !== 0) {
        continue;
      }

      const rep = reportFor(current, i);
      if (!rep) continue;

      const tension = num(rep.tension);
      const compression = num(rep.compression);
      if (!Number.isFinite(tension) || tension <= 0 ||
          !Number.isFinite(compression) || compression > 1.0) {
        continue;
      }

      const steelArea = chsArea[current.ranks[i]];
      const needed = tension / (64.3 * 0.60);
      let firstWire = -1;

      for (let w = 0; w < wire.length; w++) {
        if (wireArea[w] >= needed) {
          firstWire = w;
          break;
        }
      }

      if (firstWire < 0 || wireArea[firstWire] >= steelArea * 0.95) {
        continue;
      }

      const saving =
        (steelArea - wireArea[firstWire]) * memberLength(meta[i]);
      wireCandidates.push({ i, saving });
    }

    wireCandidates.sort((a, b) => b.saving - a.saving);

    for (const item of wireCandidates) {
      if (calls >= CALL_LIMIT) break;
      const i = item.i;

      if (current.materials[i] !== "S460" ||
          current.sections[i].indexOf("CHS") !== 0) {
        continue;
      }

      const rep = reportFor(current, i);
      if (!rep) continue;

      const tension = num(rep.tension);
      const compression = num(rep.compression);
      if (!Number.isFinite(tension) || tension <= 0 ||
          !Number.isFinite(compression) || compression > 1.0) {
        continue;
      }

      const steelArea = chsArea[current.ranks[i]];
      const needed = tension / (64.3 * 0.60);
      let firstWire = -1;

      for (let w = 0; w < wire.length; w++) {
        if (wireArea[w] >= needed) {
          firstWire = w;
          break;
        }
      }

      if (firstWire < 0) continue;

      let trials = 0;
      for (let w = firstWire;
           w < wire.length && trials < 3 && calls < CALL_LIMIT;
           w++) {
        if (wireArea[w] >= steelArea * 0.95) break;

        const trialMaterials = current.materials.slice();
        const trialSections = current.sections.slice();
        trialMaterials[i] = "WIRE";
        trialSections[i] = wire[w];

        const rec = assess(
          current.ranks,
          trialMaterials,
          trialSections
        );
        trials++;

        if (rec && rec.safe) {
          current = rec;
          break;
        }

        const failure = String(
          rec && rec.result && rec.result.failure || ""
        ).toLowerCase();
        if (failure.indexOf("mechanism") >= 0 ||
            failure.indexOf("slack") >= 0) {
          break;
        }
      }
    }
  }

  if (bestSafe) return bestSafe.design;
  if (seedRecord && seedRecord.result &&
      seedRecord.result.ok === true) {
    return seedRecord.design;
  }
  if (bestPassing) return bestPassing.design;

  return build(seedRanks, seedMaterials, seedSections);
}

