  function assess(list, y) {
    if (calls >= CALL_LIMIT) return null;

    const members = cloneMembers(list);
    const yy = y.slice();
    const d = makeDesign(members, yy);

    calls++;

    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }

    const rec = {
      design: d,
      members: members,
      y: yy,
      r: r,
      mass: massOf(r)
    };

    remember(rec);
    return rec;
  }

  function reportFor(rec, m) {
    const arr = rec && rec.r && rec.r.members;
    if (!Array.isArray(arr)) return null;

    const target = edgeKey(m.a, m.b);

    for (const item of arr) {
      if (!item) continue;

      const id = String(item.id || "");
      if (id === m.a + "-" + m.b || id === m.b + "-" + m.a) return item;

      const parts = id.split("-");
      if (parts.length === 2 && edgeKey(parts[0], parts[1]) === target) {
