  function chooseSeed(a, b) {
    if (!a) return b;
    if (!b) return a;

    if (nominalOK(a) !== nominalOK(b)) return nominalOK(a) ? a : b;
    if (robustOK(a) !== robustOK(b)) return robustOK(a) ? a : b;

    const qa = robustQuality(a);
    const qb = robustQuality(b);
