      for (let c = 0; c < Math.min(7, candidates.length) && !adopted; c++) {
        const item = candidates[c];
        const targets = [];

        if (item.info.material === "S460") {
          targets.push({
            material: "S690",
            section: item.info.section
          });
        }

        for (let r = item.rank + 1; r <= Math.min(23, item.rank + 3); r++) {
          targets.push({
            material: item.info.material,
            section: chs[r]
          });
        }

        for (const target of targets) {
          if (calls >= stopCall) break;

          const trialMembers = cloneMembers(current.members);
          trialMembers[item.i].spec = target.material + " " + target.section;
          const trial = assess(trialMembers, current.y);

          if (nominalOK(trial) &&
              (robustOK(trial) ||
               robustQuality(trial) < oldQ - 1e-5)) {
