    let current = start;
    if (!current || !nominalOK(current)) return current;

    const order = current.members.map(function (_, i) { return i; });
    order.sort(function (ia, ib) {
      const aa = sectionArea(current.members[ia].spec);
      const ab = sectionArea(current.members[ib].spec);
      const wa = (Number.isFinite(aa) ? aa : 0) *
                 memberLength(current.members[ia], current.y);
      const wb = (Number.isFinite(ab) ? ab : 0) *
                 memberLength(current.members[ib], current.y);
      return wb - wa;
    });

    function acceptable(rec) {
      return requireRobust ? robustOK(rec) : nominalOK(rec);
    }

    for (const i of order) {
      if (calls >= stopCall) break;

      const info = sectionInfo(current.members[i].spec);
      const rank = chs.indexOf(info.section);
      if (rank <= 0 || (info.material !== "S460" && info.material !== "S690")) {
        continue;
      }

      let lo = -1;
      let hi = rank;
      let hiRecord = current;

      while (hi - lo > 1 && calls < stopCall) {
        const mid = Math.floor((lo + hi) / 2);
        const trialMembers = cloneMembers(current.members);
        trialMembers[i].spec = info.material + " " + chs[mid];

        const trial = assess(trialMembers, current.y);
        if (acceptable(trial)) {
          hi = mid;
          hiRecord = trial;
        } else {
          lo = mid;
        }
      }

      if (hiRecord !== current) current = hiRecord;
    }

    return current;
  }

  const baseRec = assess(base, defaultY);
  let seed = baseRec;

  const allS690 = cloneMembers(base).map(function (m) {
    if (m.spec.indexOf("S460 ") === 0) {
      m.spec = "S690 " + m.spec.slice(5);
    }
    return m;
  });

  const s690Rec = assess(allS690, defaultY);
  if (nominalOK(s690Rec)) seed = chooseSeed(seed, s690Rec);

  seed = robustify(seed, Math.min(CALL_LIMIT - 75, calls + 24));

  const mainStop = Math.min(CALL_LIMIT - 80, calls + 230);
  seed = optimizeSections(seed, mainStop, robustOK(seed));

  // Use the available depth at the top of the allowed region.
  let source = bestRobust || bestNominal || seed;
  if (source && calls < CALL_LIMIT - 55) {
    const yHigh = source.y.slice();
    for (let i = 4; i <= 9; i++) yHigh[i] = 6.94;

    let highRec = assess(source.members, yHigh);
    if (nominalOK(highRec) && !robustOK(highRec)) {
      highRec = robustify(highRec, Math.min(CALL_LIMIT - 55, calls + 8));
    }
    if (robustOK(highRec)) {
      optimizeSections(highRec, Math.min(CALL_LIMIT - 45, calls + 18), true);
    }
  }

