  source = bestRobust || bestNominal || seed;
  if (source && calls < CALL_LIMIT - 50) {
    const yFull = source.y.slice();
    for (let i = 0; i <= 9; i++) yFull[i] = 6.94;
    yFull[13] = 6.94;
    yFull[14] = 6.94;

    let fullRec = assess(source.members, yFull);
    if (nominalOK(fullRec) && !robustOK(fullRec)) {
      fullRec = robustify(fullRec, Math.min(CALL_LIMIT - 45, calls + 7));
    }
    if (robustOK(fullRec)) {
      optimizeSections(fullRec, Math.min(CALL_LIMIT - 40, calls + 12), true);
    }
  }

  const oldDiagKeys = [
    ["D1", "U0"], ["D2", "U1"], ["D3", "U2"], ["D4", "U3"],
    ["D5", "U4"], ["D6", "U5"], ["D7", "U6"], ["D8", "U7"],
    ["D9", "U8"], ["D9", "U10"], ["D11", "U10"], ["D11", "U12"],
    ["D13", "U12"], ["D14", "U13"]
  ];

  function makePratt(sourceRec) {
    const lookup = new Map();
    for (const m of sourceRec.members) lookup.set(edgeKey(m.a, m.b), m);

    const out = sourceRec.members.filter(function (m) {
      return !isDUMember(m) || isVertical(m);
    });
    const present = new Set(out.map(function (m) {
      return edgeKey(m.a, m.b);
    }));

    function add(a, b, spec) {
      const key = edgeKey(a, b);
      if (present.has(key)) return;
      out.push({ a: a, b: b, spec: spec });
      present.add(key);
    }

    for (let i = 0; i < 14; i++) {
      const old = lookup.get(edgeKey(oldDiagKeys[i][0], oldDiagKeys[i][1]));
      const spec = old ? old.spec : "S690 CHS168.3x6.3";

      if (i < 7) {
        add("D" + (i + 1), "U" + i, spec);
      } else {
        add("D" + i, "U" + (i + 1), spec);
      }
    }

    return out;
  }

  source = bestRobust || bestNominal || seed;
  if (source && calls < CALL_LIMIT - 35) {
    let prattRec = assess(makePratt(source), source.y);

    if (nominalOK(prattRec) && !robustOK(prattRec)) {
      prattRec = robustify(
        prattRec,
        Math.min(CALL_LIMIT - 35, calls + 12)
      );
    }

    if (robustOK(prattRec)) {
      optimizeSections(
        prattRec,
        Math.min(CALL_LIMIT - 30, calls + 45),
        true
      );
    }
  }

  function makeCrossCable(sourceRec) {
    const out = sourceRec.members.filter(function (m) {
      return !isDUMember(m) || isVertical(m);
    });

    for (let i = 0; i < 14; i++) {
      if (i < 7) {
        out.push({ a: "D" + (i + 1), b: "U" + i, spec: "WIRE WIRE40" });
        out.push({ a: "D" + i, b: "U" + (i + 1), spec: "WIRE WIRE40" });
      } else {
        out.push({ a: "D" + i, b: "U" + (i + 1), spec: "WIRE WIRE40" });
        out.push({ a: "D" + (i + 1), b: "U" + i, spec: "WIRE WIRE40" });
      }
    }

    return out;
  }

  function reduceWireGroup(start, stopCall) {
    let current = start;
    if (!nominalOK(current)) return current;

    const requireRobust = robustOK(current);

    for (let rank = 6; rank >= 0 && calls < stopCall; rank--) {
      const trialMembers = cloneMembers(current.members);
      let foundWire = false;

      for (const m of trialMembers) {
        if (m.spec.indexOf("WIRE ") === 0) {
          m.spec = "WIRE " + wireSections[rank];
          foundWire = true;
        }
      }

      if (!foundWire) break;

      const trial = assess(trialMembers, current.y);
      if (requireRobust ? robustOK(trial) : nominalOK(trial)) current = trial;
      else break;
    }

    return current;
  }

  source = bestRobust || bestNominal || seed;
  if (source && calls < CALL_LIMIT - 25) {
    const xRec = assess(makeCrossCable(source), source.y);

    if (robustOK(xRec)) {
      reduceWireGroup(xRec, Math.min(CALL_LIMIT - 20, calls + 8));
    } else if (nominalOK(xRec)) {
      reduceWireGroup(xRec, Math.min(CALL_LIMIT - 20, calls + 5));
    }
  }

  function tryTensionOnlyMembers(start, stopCall) {
    let current = start;
    if (!nominalOK(current)) return current;

    for (let pass = 0; pass < 2 && calls < stopCall; pass++) {
      const candidates = [];

      for (let i = 0; i < current.members.length; i++) {
        const m = current.members[i];
        const info = sectionInfo(m.spec);
        const rank = chs.indexOf(info.section);
        if (rank < 0 || !isDUMember(m)) continue;

        const report = reportFor(current, m);
        if (!report) continue;

        const tension = num(report.tension);
        const compression = num(report.compression);
        const u = normUtil(report.util);
        if (!Number.isFinite(tension) || tension <= 0) continue;
        if (!Number.isFinite(compression) || compression > 0.5) continue;

        const a = chsArea[rank];
        const forceNeed = tension / 55.0;
        const fatigueNeed = Number.isFinite(u) ? u * a * 9 / 11 * 1.12 : 0;
        const required = Math.max(0.35, forceNeed, fatigueNeed);

        let first = -1;
        for (let w = 0; w < wireArea.length; w++) {
          if (wireArea[w] >= required) {
            first = w;
            break;
          }
        }

        if (first < 0 || wireArea[first] >= a * 0.90) continue;

        candidates.push({
          i: i,
          first: first,
          saving: (a - wireArea[first]) * memberLength(m, current.y)
        });
      }

      candidates.sort(function (a, b) { return b.saving - a.saving; });

      let changed = false;
      const requireRobust = robustOK(current);

      for (const item of candidates) {
        if (calls >= stopCall) break;

        const currentMember = current.members[item.i];
        const currentInfo = sectionInfo(currentMember.spec);
        if (chs.indexOf(currentInfo.section) < 0) continue;

        for (let w = item.first;
             w <= Math.min(item.first + 2, 7) && calls < stopCall;
             w++) {
          const trialMembers = cloneMembers(current.members);
          trialMembers[item.i].spec = "WIRE " + wireSections[w];

          const trial = assess(trialMembers, current.y);
          const accepted = requireRobust ? robustOK(trial) : nominalOK(trial);

          if (accepted && trial.mass < current.mass - 1e-7) {
            current = trial;
            changed = true;
            break;
          }
        }

        if (changed) break;
      }

      if (!changed) break;
    }

    return current;
  }

  source = bestRobust || bestNominal || seed;
  if (source && calls < CALL_LIMIT) {
    tryTensionOnlyMembers(source, Math.min(CALL_LIMIT, calls + 25));
  }

  if (bestRobust &&
      (!bestNominal || bestRobust.mass <= bestNominal.mass * 1.05)) {
    return bestRobust.design;
  }

  if (bestNominal) return bestNominal.design;
  if (baseRec && baseRec.design) return baseRec.design;

  return makeDesign(base, defaultY);
}

