  function reportFor(rec, m) {
    const arr = rec && rec.r && rec.r.members;
    if (!Array.isArray(arr)) return null;

    const target = edgeKey(m.a, m.b);
    for (const item of arr) {
      if (!item) continue;
      const id = String(item.id || "");
      if (id === m.a + "-" + m.b || id === m.b + "-" + m.a) return item;

      const parts = id.split("-");
      if (parts.length === 2 && edgeKey(parts[0], parts[1]) === target) {
        return item;
      }
    }
    return null;
  }

  function sectionArea(spec) {
    const info = sectionInfo(spec);
    const ci = chs.indexOf(info.section);
    if (ci >= 0) return chsArea[ci];

    const wi = wireSections.indexOf(info.section);
    if (wi >= 0) return wireArea[wi];

    return 0;
  }

  function isDUMember(m) {
    const a = String(m.a);
    const b = String(m.b);
    return (a.charAt(0) === "D" && b.charAt(0) === "U") ||
           (a.charAt(0) === "U" && b.charAt(0) === "D");
  }

  function isIndexedVertical(m) {
    if (!isDUMember(m)) return false;
    const a = String(m.a);
    const b = String(m.b);
