    for (const m of source) lookup.set(edgeKey(m.a, m.b), m);

    const out = source.filter(function (m) {
      return !isDUMember(m) || isIndexedVertical(m);
    });
    const present = new Set(out.map(function (m) {
      return edgeKey(m.a, m.b);
    }));

