  }

  function addCrossCables(source, firstPanel, lastPanel) {
    const out = copyList(source);
    const present = new Set(out.map(function (m) {
      return edgeKey(m.a, m.b);
    }));

    for (let i = firstPanel; i <= lastPanel; i++) {
      const a1 = "D" + i;
      const b1 = "U" + (i + 1);
      const a2 = "D" + (i + 1);
      const b2 = "U" + i;
      const k1 = edgeKey(a1, b1);
      const k2 = edgeKey(a2, b2);
      const has1 = present.has(k1);
      const has2 = present.has(k2);

      if (has1 && has2) continue;
      if (has1) {
        out.push({ a: a2, b: b2, spec: "WIRE WIRE40" });
