    if (!current || !safeResult(current.r)) return current;

    const order = current.list.map(function (_, i) { return i; });
    order.sort(function (ia, ib) {
      const wa = sectionArea(current.list[ia].spec) *
                 memberLength(current.list[ia], current.y);
      const wb = sectionArea(current.list[ib].spec) *
                 memberLength(current.list[ib], current.y);
      return wb - wa;
