    function shrinkWire(cur, i) {
      const info = sectionInfo(cur.list[i].spec);
      const rank = wireSections.indexOf(info.section);
      if (rank <= 0) return cur;

      let lo = -1;
      let hi = rank;
      let hiRecord = cur;

      while (hi - lo > 1 && calls < stopCall) {
        const mid = Math.floor((hi + lo) / 2);
        const trialList = copyList(cur.list);
        trialList[i].spec = "WIRE " + wireSections[mid];
        const trial = assess(trialList, cur.y);

        if (trial && safeResult(trial.r)) {
          hi = mid;
          hiRecord = trial;
        } else {
          lo = mid;
        }
      }

      return better(hiRecord, cur) ? hiRecord : cur;
    }

    function shrinkSteel(cur, i) {
      const info = sectionInfo(cur.list[i].spec);
      const rank = chs.indexOf(info.section);
      if (rank <= 0 || (info.material !== "S460" && info.material !== "S690")) {
        return cur;
      }

      const rep = reportFor(cur, cur.list[i]);
      const mode = String(rep && rep.mode || "").toLowerCase();
      const compression = num(rep && rep.compression);
      const targets = [info.material];

      if (info.material === "S460" &&
          mode.indexOf("fatigue") < 0 &&
          (mode.indexOf("buckl") >= 0 ||
           mode.indexOf("compress") >= 0 ||
           mode.indexOf("interaction") >= 0 ||
           (Number.isFinite(compression) && compression > 20))) {
        targets.push("S690");
      }

      let chosen = cur;

      for (const material of targets) {
        if (calls >= stopCall) break;

        let lo = -1;
        let hi = rank;
        let hiRecord = null;

        if (material === info.material) {
          hiRecord = cur;
        } else {
          const trialList = copyList(cur.list);
          trialList[i].spec = material + " " + chs[rank];
          const trial = assess(trialList, cur.y);
          if (!trial || !safeResult(trial.r)) continue;
          hiRecord = trial;
        }

        while (hi - lo > 1 && calls < stopCall) {
          const mid = Math.floor((hi + lo) / 2);
          const trialList = copyList(cur.list);
          trialList[i].spec = material + " " + chs[mid];
          const trial = assess(trialList, cur.y);

          if (trial && safeResult(trial.r)) {
            hi = mid;
            hiRecord = trial;
          } else {
            lo = mid;
          }
        }

        if (better(hiRecord, chosen)) chosen = hiRecord;
      }

      return chosen;
    }

    for (const i of order) {
      if (calls >= stopCall) break;

      const info = sectionInfo(current.list[i].spec);
      if (info.material === "WIRE") {
        current = shrinkWire(current, i);
      } else if (info.section.indexOf("CHS") === 0) {
