    return current;
  }

  const baseRec = assess(base, defaultY);

  const highY = defaultY.slice();
  for (let i = 4; i <= 9; i++) highY[i] = 6.94;
  const highRec = calls < CALL_LIMIT ? assess(base, highY) : null;

  const prattRec = calls < CALL_LIMIT
    ? assess(makePratt(base), defaultY)
    : null;

  const cableList = addCrossCables(base, 2, 11);
  const cableRec = calls < CALL_LIMIT
    ? assess(cableList, defaultY)
    : null;

  if (baseRec && safeResult(baseRec.r) && calls < CALL_LIMIT) {
    optimize(baseRec, Math.min(CALL_LIMIT, calls + 145));
  }

  if (cableRec && safeResult(cableRec.r) && calls < CALL_LIMIT) {
    optimize(cableRec, Math.min(CALL_LIMIT, calls + 135));
  }

  let alternative = null;
  for (const candidate of [highRec, prattRec]) {
    if (candidate && safeResult(candidate.r) && better(candidate, alternative)) {
      alternative = candidate;
    }
  }
  if (alternative && calls < CALL_LIMIT) {
    optimize(alternative, Math.min(CALL_LIMIT, calls + 100));
  }

  if (bestSafe && calls < CALL_LIMIT) {
    optimize(bestSafe, CALL_LIMIT);
  }

  if (bestSafe) return bestSafe.design;
  if (bestNominal) return bestNominal.design;
  return makeDesign(base, defaultY);
