  function findDiag(source, panel) {
    for (const m of source) {
      if (panelOf(m) === panel) return m;
    }
    return null;
  }

  function standardOrientation(panel) {
    if (panel < 7) {
      return { a: "D" + (panel + 1), b: "U" + panel };
    }
    return { a: "D" + panel, b: "U" + (panel + 1) };
  }

  function oppositeOrientation(a, b) {
    const ix = duIndices({ a: a, b: b });
    const panel = Math.min(ix.d, ix.u);
    if (ix.d === panel) {
      return { a: "D" + (panel + 1), b: "U" + panel };
    }
    return { a: "D" + panel, b: "U" + (panel + 1) };
  }

  function steelForPanel(source, panel) {
    const old = findDiag(source, panel);
    return old
      ? to690(old.spec)
      : "S690 CHS193.7x6.3";
  }

  function makeCrossCableWeb(source) {
    const out = fixedParts(source);

    for (let i = 0; i < 14; i++) {
      if (i === 9) {
        // D10-U9 is nearly parallel to U9-U10, so retain a steel brace here.
        const st = standardOrientation(i);
        out.push({
          a: st.a,
          b: st.b,
          spec: steelForPanel(source, i)
        });
      } else {
        out.push({
          a: "D" + i,
          b: "U" + (i + 1),
          spec: "WIRE WIRE40"
        });
        out.push({
          a: "D" + (i + 1),
          b: "U" + i,
          spec: "WIRE WIRE40"
        });
      }
    }

    return out;
  }

  function makeHybridWeb(source) {
    const out = fixedParts(source);

    for (let i = 0; i < 14; i++) {
      const st = standardOrientation(i);
      out.push({
        a: st.a,
        b: st.b,
        spec: steelForPanel(source, i)
      });

      if (i !== 9) {
        const opposite = oppositeOrientation(st.a, st.b);
        out.push({
          a: opposite.a,
          b: opposite.b,
          spec: "WIRE WIRE40"
        });
      }
    }

    return out;
  }

  function makePrattWeb(source) {
    const out = fixedParts(source);

    for (let i = 0; i < 14; i++) {
      const st = standardOrientation(i);
      out.push({
        a: st.a,
        b: st.b,
        spec: steelForPanel(source, i)
      });
    }

    return out;
