  function makeMixedWeb(source, sourceRec) {
    const out = fixedParts(source);

    for (let i = 0; i < 14; i++) {
      let old = findDiag(source, i);
      if (!old) {
        const st = standardOrientation(i);
        old = {
          a: st.a,
          b: st.b,
          spec: "S690 CHS193.7x6.3"
        };
      }

      const report = reportFor(sourceRec, old);
      const compression = num(report && report.compression);
      const tension = num(report && report.tension);
      const replaceWithWire =
        i !== 9 &&
        Number.isFinite(compression) &&
        compression <= 0.5 &&
        Number.isFinite(tension) &&
        tension > 0;

      out.push({
        a: old.a,
        b: old.b,
        spec: replaceWithWire ? "WIRE WIRE40" : to690(old.spec)
      });

      if (i !== 9) {
        const opposite = oppositeOrientation(old.a, old.b);
        out.push({
          a: opposite.a,
          b: opposite.b,
          spec: "WIRE WIRE40"
        });
      }
    }

    return out;
  }

  function optionsFor(info) {
    if (info.material === "WIRE" &&
        wireSections.indexOf(info.section) >= 0) {
      return wireOptions;
    }

    if ((info.material === "S460" || info.material === "S690") &&
        chs.indexOf(info.section) >= 0) {
      return chsOptions;
    }

    return null;
  }

  function optionIndex(options, section) {
    for (let i = 0; i < options.length; i++) {
      if (options[i].section === section) return i;
    }
    return -1;
  }

  function optimizeSections(start, stopCall) {
    let current = start;
    if (!current || !nominalOK(current)) return current;

    const mode = rankLevel(current);
    if (mode < 0) return current;

    const order = current.list.map(function (m, i) {
      return { i: i, weight: sectionArea(m.spec) * memberLength(m, current.y) };
    }).sort(function (a, b) {
      return b.weight - a.weight;
    }).map(function (x) {
      return x.i;
    });

    for (const memberIndex of order) {
      if (calls >= stopCall) break;

      const info = sectionInfo(current.list[memberIndex].spec);
      const options = optionsFor(info);
      if (!options) continue;

      const rank = optionIndex(options, info.section);
      if (rank <= 0) continue;

      let lo = -1;
      let hi = rank;
      let hiRecord = current;

      while (hi - lo > 1 && calls < stopCall) {
        const mid = Math.floor((hi + lo) / 2);
        const trialList = copyList(current.list);
        trialList[memberIndex].spec =
          info.material + " " + options[mid].section;

        const trial = assess(trialList, current.y, "section reduction");
        if (trial && guard(trial, mode)) {
          hi = mid;
          hiRecord = trial;
        } else {
          lo = mid;
        }
      }

      current = hiRecord;
    }

    return current;
  }

  function reinforceForMargin(start, stopCall) {
    let current = start;
    if (!current || !guard(current, 1)) return current;

    for (let step = 0; step < 5 && calls < stopCall; step++) {
      if (guard(current, 2)) break;

      const q0 = riskQuality(current);
      const order = current.list.map(function (m, i) {
        const info = sectionInfo(m.spec);
        const options = optionsFor(info);
        const rank = options ? optionIndex(options, info.section) : -1;
        const chordFactor = isChord(m) ? 2.5 : 1.0;
        return {
          i: i,
          options: options,
          rank: rank,
          priority: chordFactor *
            sectionArea(m.spec) * memberLength(m, current.y)
        };
      }).filter(function (x) {
        return x.options && x.rank >= 0 && x.rank + 1 < x.options.length;
      }).sort(function (a, b) {
        return b.priority - a.priority;
      });

      let bestTrial = null;
      let bestQ = q0;

      for (let j = 0; j < Math.min(8, order.length); j++) {
        if (calls >= stopCall) break;

        const item = order[j];
        const m = current.list[item.i];
        const info = sectionInfo(m.spec);
        const trialList = copyList(current.list);
        trialList[item.i].spec =
          info.material + " " + item.options[item.rank + 1].section;

        const trial = assess(trialList, current.y, "margin reinforcement");
        if (!trial || !guard(trial, 1)) continue;

        const q = riskQuality(trial);
        if (q < bestQ - 1e-5) {
          bestQ = q;
          bestTrial = trial;
        }
      }

      if (!bestTrial) break;
      current = bestTrial;
    }

    return current;
  }

  const deckSections = [
    "CHS42.4x3.2",
    "CHS457x16", "CHS457x16", "CHS457x16",
    "CHS406.4x12.5", "CHS457x16",
    "CHS406.4x12.5", "CHS406.4x12.5", "CHS406.4x12.5",
    "CHS457x16", "CHS457x16",
    "CHS406.4x12.5", "CHS406.4x12.5",
    "CHS139.7x5"
