  const webRows = [
    ["D0", "U0", "S460 CHS355.6x12.5"],
    ["D1", "U0", "S460 CHS355.6x12.5"],
    ["D1", "U1", "S690 CHS168.3x6.3"],
    ["D2", "U1", "S460 CHS244.5x8"],
    ["D2", "U2", "S690 CHS168.3x6.3"],
    ["D3", "U2", "S460 CHS168.3x6.3"],
    ["D3", "U3", "S460 CHS168.3x6.3"],
    ["D4", "U3", "S460 CHS168.3x6.3"],
    ["D4", "U4", "S460 CHS168.3x6.3"],
    ["D5", "U4", "S460 CHS193.7x6.3"],
    ["D5", "U5", "S690 CHS168.3x6.3"],
    ["D6", "U5", "S460 CHS193.7x6.3"],
    ["D6", "U6", "S460 CHS168.3x6.3"],
    ["D7", "U6", "S460 CHS193.7x6.3"],
    ["D7", "U7", "S460 CHS168.3x6.3"],
    ["D8", "U7", "S460 CHS193.7x6.3"],
    ["D8", "U8", "S460 CHS168.3x6.3"],
    ["D9", "U8", "S460 CHS193.7x6.3"],
    ["D9", "U9", "S460 CHS273x10"],
    ["D9", "U10", "S460 CHS355.6x12.5"],
    ["D10", "U10", "S460 CHS114.3x5"],
    ["D11", "U10", "S460 CHS219.1x8"],
    ["D11", "U11", "S460 CHS42.4x3.2"],
    ["D11", "U12", "S460 CHS193.7x8"],
    ["D12", "U12", "S460 CHS114.3x5"],
    ["D13", "U12", "S460 CHS273x10"],
    ["D13", "U13", "S460 CHS323.9x10"],
    ["D14", "U13", "S460 CHS244.5x8"],
    ["D14", "U14", "S460 CHS33.7x2.6"]
  ];

  const base = [];

  for (let i = 0; i < 14; i++) {
    base.push({
      a: "D" + i,
      b: "D" + (i + 1),
      spec: "S460 " + deckSections[i]
    });
  }

  for (let i = 0; i < 14; i++) {
    base.push({
      a: "U" + i,
      b: "U" + (i + 1),
      spec: "S460 " + topSections[i]
    });
  }

  for (const row of webRows) {
    base.push({ a: row[0], b: row[1], spec: row[2] });
  }

  base.push(
    { a: "S1", b: "D0", spec: "S460 CHS355.6x12.5" },
    { a: "S1", b: "D1", spec: "S460 CHS355.6x12.5" },
    { a: "D14", b: "S2", spec: "S690 CHS193.7x8" },
    { a: "D13", b: "S2", spec: "S460 CHS33.7x2.6" }
  );

  const seedRecords = [];

  const baseRec = assess(base, yDefault, "published passing design");
  if (baseRec) seedRecords.push(baseRec);

  const high690 = base.map(function (m) {
    return { a: m.a, b: m.b, spec: to690(m.spec) };
  });

  const high690Rec = assess(high690, yHigh, "high profile S690");
  if (high690Rec) seedRecords.push(high690Rec);

  const crossRec = assess(
    makeCrossCableWeb(base),
    yHigh,
    "crossed cable web"
  );
  if (crossRec) seedRecords.push(crossRec);

  const hybridRec = assess(
    makeHybridWeb(base),
    yHigh,
    "hybrid Pratt cable web"
  );
  if (hybridRec) seedRecords.push(hybridRec);

  if (baseRec) {
    const mixedRec = assess(
      makeMixedWeb(base, baseRec),
      yHigh,
      "report-selected mixed web"
    );
    if (mixedRec) seedRecords.push(mixedRec);
  }

  const prattRec = assess(
    makePrattWeb(base),
    yHigh,
    "single diagonal Pratt web"
  );
  if (prattRec) seedRecords.push(prattRec);

  function signature(rec) {
    const items = rec.list.map(function (m) {
      return edgeKey(m.a, m.b) + ":" + m.spec;
    }).sort();
    return rec.y.join(",") + "#" + items.join(";");
  }

  function seedPriority(rec) {
    const level = rankLevel(rec);
    return rec.mass +
      (2 - level) * 350 +
      50 * Math.max(0, riskQuality(rec) - 1);
  }

  const pool = [];
  const seen = new Set();

  for (const rec of seedRecords) {
    if (!rec || rec === baseRec || !nominalOK(rec) ||
        rankLevel(rec) < 0) continue;

    const key = signature(rec);
    if (seen.has(key)) continue;
    seen.add(key);
    pool.push(rec);
  }

  pool.sort(function (a, b) {
    return seedPriority(a) - seedPriority(b);
  });

  const selected = pool.slice(0, 3);

  for (let i = 0; i < selected.length; i++) {
    const slotsLeft = selected.length - i;
    const reserve = 35;
    const available = CALL_LIMIT - reserve - calls;
    if (available <= 0) break;

    const share = Math.max(1, Math.floor(available / slotsLeft));
    const stopCall = Math.min(CALL_LIMIT - 30, calls + share);
    optimizeSections(selected[i], stopCall);
  }

  if (!bestLevel2 && bestLevel1 && calls < CALL_LIMIT) {
    reinforceForMargin(
      bestLevel1,
      Math.min(CALL_LIMIT, calls + 35)
    );
  }

  const finalRec =
    bestLevel2 || bestLevel1 || bestNominal || baseRec;

  if (finalRec) return finalRec.design;

  return makeDesign(base, yDefault);
}

