    if (!Number.isFinite(limit) || limit <= 0) limit = 0.1287;

    if (s > 1 && limit < 1) s /= 1000;
    else if (s < 1 && limit > 1) s *= 1000;

    return s / limit;
  }

  function fatigueUse(r) {
    const f = r && r.fatigueWorst;
    const direct = num(f);

    if (Number.isFinite(direct)) {
      const a = Math.abs(direct);
      return a > 2 ? a / 90 : a;
    }

    if (f && typeof f === "object") {
      for (const key of ["util", "utilization", "ratio", "usage"]) {
        const u = normUtil(f[key]);
        if (Number.isFinite(u)) return u;
      }

      let range = NaN;
      for (const key of [
        "range", "stressRange", "deltaSigma", "stress", "value"
      ]) {
        range = num(f[key]);
        if (Number.isFinite(range)) break;
      }

      if (Number.isFinite(range)) {
        let limit = num(f.limit);
        if (!Number.isFinite(limit) || limit <= 0) limit = 90;
        return Math.abs(range) / limit;
      }
    }

    return NaN;
  }

  function nominalOK(rec) {
    return !!(
      rec &&
      rec.r &&
      rec.r.ok === true &&
      !rec.r.error &&
      Number.isFinite(rec.mass)
    );
  }

  function frequencyTarget(rec) {
    const r = rec && rec.r;
    let fMin = num(r && r.fMin);
    if (!Number.isFinite(fMin) || fMin <= 0) fMin = 2.5;

    let target = Math.max(2.62, fMin + 0.12, fMin * 1.05);

    let total = 0;
    let wood = 0;
    if (rec && Array.isArray(rec.list)) {
      for (const m of rec.list) {
        const w = massPerMetre(m.spec) * memberLength(m, rec.y);
        if (Number.isFinite(w) && w > 0) {
          total += w;
          if (sectionInfo(m.spec).material === "GL28") wood += w;
        }
      }
    }

    if (total > 0 && wood > 0) {
      const share = Math.min(1, 2 * wood / total);
      const eLower = 0.97 *
        (1 - (1 - 0.85 / 0.97) * share);
      const builtTarget = 2.5 / Math.sqrt(Math.max(0.70, eLower)) + 0.025;
      target = Math.max(target, builtTarget);
    }

    return target;
  }

  function strongQ(rec) {
    if (!nominalOK(rec)) return Infinity;

    const u = utilOf(rec.r);
    const s = sagRatio(rec.r);
    const f = num(rec.r.frequency);
    const fatigue = fatigueUse(rec.r);

    if (!Number.isFinite(u) || !Number.isFinite(s) ||
        !Number.isFinite(f) || f <= 0) return Infinity;

    let q = Math.max(
      u / 0.64,
      s / 0.84,
      frequencyTarget(rec) / f
    );

    if (Number.isFinite(fatigue)) q = Math.max(q, fatigue / 0.64);
    return q;
  }

  function softQ(rec) {
    if (!nominalOK(rec)) return Infinity;

    const u = utilOf(rec.r);
    const s = sagRatio(rec.r);
    const f = num(rec.r.frequency);
    const fatigue = fatigueUse(rec.r);

    if (!Number.isFinite(u) || !Number.isFinite(s) ||
        !Number.isFinite(f) || f <= 0) return Infinity;

    let q = Math.max(
      u / 0.82,
      s / 0.95,
      frequencyTarget(rec) / f
    );

    if (Number.isFinite(fatigue)) q = Math.max(q, fatigue / 0.82);
    return q;
  }

  function massOf(r) {
    const m = num(r && r.mass);
    if (Number.isFinite(m)) return m;

    const score = num(r && r.score);
    if (Number.isFinite(score) && score > 0) {
      return 18623 * 100 / score;
    }
    return Infinity;
  }

  function betterMass(a, b) {
    if (!a) return false;
    if (!b) return true;
    if (a.mass < b.mass - 1e-7) return true;
    if (Math.abs(a.mass - b.mass) <= 1e-7) {
      return strongQ(a) < strongQ(b) - 1e-8;
    }
    return false;
  }

  function remember(rec) {
    if (!nominalOK(rec)) return;

    if (betterMass(rec, bestNominal)) bestNominal = rec;

    const q = strongQ(rec);
    if (Number.isFinite(q)) {
      if (!bestQ || q < strongQ(bestQ) - 1e-8 ||
          (Math.abs(q - strongQ(bestQ)) <= 1e-8 &&
           rec.mass < bestQ.mass)) {
        bestQ = rec;
      }

      if (q <= 1.080001 && betterMass(rec, bestNear)) bestNear = rec;
      if (q <= 1.000501 && betterMass(rec, bestStrong)) bestStrong = rec;
    }
  }

  function assess(list, y, tag) {
    if (calls >= CALL_LIMIT) return null;

    const members = copyList(list);
    const yy = y.slice();
    const d = makeDesign(members, yy);
    calls++;

    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }

    const rec = {
      design: d,
      list: members,
      y: yy,
      r: r,
      mass: massOf(r),
      tag: tag || ""
    };

    remember(rec);
    return rec;
  }

  function reportFor(rec, m) {
    const arr = rec && rec.r && rec.r.members;
    if (!Array.isArray(arr)) return null;

    const target = edgeKey(m.a, m.b);
    for (const item of arr) {
      if (!item) continue;
      const id = String(item.id || "");
      const parts = id.split("-");
      if (parts.length === 2 &&
          edgeKey(parts[0], parts[1]) === target) {
        return item;
      }
    }
    return null;
  }

  function sectionOptions(m) {
    const info = sectionInfo(m.spec);

    if ((info.material === "S690" || info.material === "AL6082") &&
        info.section.indexOf("CHS") === 0) {
      return chsOptions;
    }

    if (info.material === "GL28" &&
        info.section.indexOf("TIMBER") === 0) {
      return timberOptions;
    }

    return null;
  }

  function optionRank(options, section) {
    if (!options) return -1;
    for (let i = 0; i < options.length; i++) {
      if (options[i].section === section) return i;
    }
    return -1;
  }

  function isChord(m) {
    const a = String(m.a).charAt(0);
    const b = String(m.b).charAt(0);
    return (a === "D" && b === "D") || (a === "U" && b === "U");
  }

  function reportForce(rep, keyA, keyB) {
    if (!rep) return 0;
    let v = num(rep[keyA]);
    if (!Number.isFinite(v)) v = num(rep[keyB]);
    return Number.isFinite(v) ? Math.abs(v) : 0;
  }

  function timberRanks(rec, m) {
    const rep = reportFor(rec, m);
    const tension = reportForce(rep, "tension", "maxTension");
    const compression = reportForce(rep, "compression", "maxCompression");
    const force = Math.max(tension, compression);
    const length = memberLength(m, rec.y);

    const requiredArea = Math.max(162, 0.90 * force);
    let target = 0;
    while (target < timberOptions.length - 1 &&
           timberOptions[target].area < requiredArea) {
      target++;
    }

    let minimum = 0;
    if (compression > 0.35 * Math.max(force, 1)) {
      if (length >= 7.0 && compression > 80) {
        minimum = 3;
      } else if (length >= 5.5 && compression > 40) {
        minimum = 2;
      } else if (length >= 4.5 && compression > 180) {
        minimum = 2;
      }
    }

    target = Math.max(target, minimum);

    const ranks = [];
    for (let i = Math.max(minimum, target - 1);
         i <= Math.min(timberOptions.length - 1, target + 2);
         i++) {
      if (ranks.indexOf(i) < 0) ranks.push(i);
    }
    return ranks;
  }

  const baseRec = assess(base, yHigh, "tested pinned high-depth truss");
  if (!nominalOK(baseRec)) return makeDesign(base, yHigh);

  let current = baseRec;
  const substitutionCap = softQ(baseRec) + 0.035;
  const materialStop = Math.min(CALL_LIMIT, calls + 145);

  const materialOrder = current.list.map(function (m, i) {
    return {
      i: i,
      weight: sectionAreaCm2(m.spec) * memberLength(m, current.y)
    };
  }).sort(function (a, b) {
    return b.weight - a.weight;
  }).map(function (v) {
    return v.i;
  });

  for (const index of materialOrder) {
    if (calls >= materialStop) break;

    const m = current.list[index];
    const info = sectionInfo(m.spec);
    const oldWeight = massPerMetre(m.spec);

    if ((info.material !== "S690" && info.material !== "AL6082") ||
        info.section.indexOf("CHS") !== 0 ||
        oldWeight < 18) {
      continue;
    }

    const alternatives = [];

    if (info.material === "S690") {
      const rank = optionRank(chsOptions, info.section);
      if (rank >= 0) {
        for (let r = rank; r <= Math.min(rank + 1, chsOptions.length - 1); r++) {
          alternatives.push("AL6082 " + chsOptions[r].section);
        }
      }
    }

    for (const rank of timberRanks(current, m)) {
      alternatives.push("GL28 " + timberOptions[rank].section);
    }

    let winner = null;
    let winnerScore = Infinity;

    for (const spec of alternatives) {
      if (calls >= materialStop) break;
      if (massPerMetre(spec) >= oldWeight - 0.05) continue;

      const trialList = copyList(current.list);
      trialList[index].spec = spec;
      const trial = assess(trialList, current.y, "material substitution");

      if (!nominalOK(trial) ||
          trial.mass >= current.mass - 0.5 ||
          softQ(trial) > substitutionCap ||
          strongQ(trial) > strongQ(current) + 0.14) {
        continue;
      }

      const score = trial.mass +
        350 * Math.max(0, softQ(trial) - 1) +
        450 * Math.max(0, strongQ(trial) - 1);

      if (score < winnerScore) {
        winnerScore = score;
        winner = trial;
      }
    }

    if (winner) current = winner;
  }

  function trimSections(start, stopCall, mode, maxMembers) {
    let cur = start;
    if (!cur || !nominalOK(cur)) return cur;

    const softCap = softQ(start) + (mode === "strong" ? 0.025 : 0.012);
    const strongCap = mode === "strong"
      ? 1.000501
      : strongQ(start) + (mode === "preserve" ? 0.006 : 0.015);

    const order = cur.list.map(function (m, i) {
      return {
        i: i,
        weight: massPerMetre(m.spec) * memberLength(m, cur.y)
      };
    }).sort(function (a, b) {
      return b.weight - a.weight;
    }).slice(0, maxMembers).map(function (v) {
      return v.i;
    });

    function acceptable(trial) {
      if (!nominalOK(trial)) return false;
      if (softQ(trial) > softCap) return false;
      if (strongQ(trial) > strongCap) return false;
      return true;
    }

    for (const index of order) {
      if (calls >= stopCall) break;

      const m = cur.list[index];
      const options = sectionOptions(m);
      const info = sectionInfo(m.spec);
      const rank = optionRank(options, info.section);

      if (!options || rank <= 0) continue;

      let lo = -1;
      let hi = rank;
      let chosen = cur;

      while (hi - lo > 1 && calls < stopCall) {
        const mid = Math.floor((hi + lo) / 2);
        const trialList = copyList(cur.list);
        trialList[index].spec =
          info.material + " " + options[mid].section;

        const trial = assess(trialList, cur.y, "section reduction");

        if (acceptable(trial)) {
          hi = mid;
          chosen = trial;
        } else {
          lo = mid;
        }
      }

      if (chosen && chosen.mass < cur.mass - 0.1) cur = chosen;
    }

    return cur;
  }

  const trimStop = Math.min(CALL_LIMIT, calls + 125);
  current = trimSections(current, trimStop, "soft", 45);

  function reinforcementCandidates(rec) {
    const chosen = [];
    const seen = new Set();

    function add(i) {
      if (i < 0 || i >= rec.list.length || seen.has(i)) return;
      seen.add(i);
      chosen.push(i);
    }

    const ranked = rec.list.map(function (m, i) {
      const rep = reportFor(rec, m);
      const util = normUtil(rep && rep.util);
      return {
        i: i,
        util: Number.isFinite(util) ? util : -1,
        weight: massPerMetre(m.spec) * memberLength(m, rec.y)
      };
    }).sort(function (a, b) {
      return b.util - a.util;
    });

    for (const item of ranked.slice(0, 16)) add(item.i);

    const f = num(rec.r && rec.r.frequency);
    if (Number.isFinite(f) && f < frequencyTarget(rec) * 1.015) {
      const chords = rec.list.map(function (m, i) {
        return {
          i: i,
          chord: isChord(m),
          weight: massPerMetre(m.spec) * memberLength(m, rec.y)
        };
      }).filter(function (v) {
        return v.chord;
      }).sort(function (a, b) {
        return b.weight - a.weight;
      });

      for (const item of chords.slice(0, 12)) add(item.i);
    }

    const highWeight = rec.list.map(function (m, i) {
      return {
        i: i,
        weight: massPerMetre(m.spec) * memberLength(m, rec.y)
      };
    }).sort(function (a, b) {
      return b.weight - a.weight;
    });

    for (const item of highWeight.slice(0, 5)) add(item.i);
    return chosen.slice(0, 24);
  }

  function reinforce(start, stopCall) {
    let cur = start;
    if (!cur || !nominalOK(cur)) return cur;

    for (let step = 0; step < 9 && calls < stopCall; step++) {
      const q0 = strongQ(cur);
      if (q0 <= 1.000501) break;

      const indices = reinforcementCandidates(cur);
      let bestTrial = null;
      let bestValue = 0;

      for (const index of indices) {
        if (calls >= stopCall) break;

        const m = cur.list[index];
        const info = sectionInfo(m.spec);
        const options = sectionOptions(m);
        const rank = optionRank(options, info.section);

        if (!options || rank < 0 || rank + 1 >= options.length) continue;

        const trialList = copyList(cur.list);
        trialList[index].spec =
          info.material + " " + options[rank + 1].section;

        const trial = assess(trialList, cur.y, "reserve reinforcement");
        if (!nominalOK(trial)) continue;

        const q1 = strongQ(trial);
        const improvement = q0 - q1;
        if (!Number.isFinite(q1) || improvement <= 0.0002) continue;

        const addedMass = Math.max(0, trial.mass - cur.mass);
        const value = improvement / (addedMass + 35);

        if (value > bestValue ||
            (Math.abs(value - bestValue) < 1e-10 &&
             bestTrial && q1 < strongQ(bestTrial))) {
          bestValue = value;
          bestTrial = trial;
        }
      }

      if (!bestTrial) break;
      cur = bestTrial;
    }

    return cur;
  }

  const reinforcementStop = Math.min(CALL_LIMIT, calls + 100);
  current = reinforce(current, reinforcementStop);

  if (bestStrong) {
    trimSections(bestStrong, CALL_LIMIT, "strong", 50);
  } else if (bestNear) {
    trimSections(bestNear, CALL_LIMIT, "preserve", 32);
  }

  const finalRec =
    bestStrong || bestNear || bestQ || bestNominal || baseRec;

  return finalRec.design;
}

function design(site, analyse) {
  const note = "S690 CHS variable-depth Pratt truss with low right-side clearance and S1-D2 brace; per-member greedy sizing with robustness margins.";

  const dx = [0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3, 22.057, 24.814, 27.571, 30.329, 33.086, 35.843, 38.6];
  const yTop = [3.0, 4.0, 5.0, 5.8, 6.4, 6.8, 6.9, 6.9, 6.4, 5.0, 2.0, 2.0, 2.2, 5.0, 3.0];

  const nodes = [];
  for (let i = 0; i < 15; i++) {
    nodes.push({ id: "T" + i, x: dx[i], y: yTop[i], joint: "pin" });
  }

  const defs = [];
  // bottom chord
  for (let i = 0; i < 14; i++) defs.push(["D" + i, "D" + (i + 1)]);
  // top chord
  for (let i = 0; i < 14; i++) defs.push(["T" + i, "T" + (i + 1)]);
  // verticals
  for (let i = 0; i < 15; i++) defs.push(["D" + i, "T" + i]);
  // diagonals: left half \ (T_i-D_{i+1}), right half / (D_i-T_{i+1})
  for (let i = 0; i <= 6; i++) defs.push(["T" + i, "D" + (i + 1)]);
  for (let i = 7; i <= 13; i++) defs.push(["D" + i, "T" + (i + 1)]);
  // support/support-bracing members
  defs.push(["S1", "D0"]);
  defs.push(["S1", "D1"]);
  defs.push(["S1", "D2"]);
  defs.push(["S2", "D14"]);

  const n = defs.length;

  const candIds = [
    "CHS33.7x2.6",
    "CHS42.4x3.2",
    "CHS48.3x3.2",
    "CHS60.3x3.2",
    "CHS60.3x4",
    "CHS76.1x3.2",
    "CHS76.1x4",
    "CHS88.9x4",
    "CHS88.9x5",
    "CHS114.3x4",
    "CHS114.3x5",
    "CHS139.7x5",
    "CHS168.3x5",
    "CHS139.7x6.3",
    "CHS168.3x6.3",
    "CHS193.7x6.3",
    "CHS193.7x8",
    "CHS219.1x8",
    "CHS244.5x8",
    "CHS273x10",
    "CHS323.9x10",
    "CHS355.6x12.5",
    "CHS406.4x12.5",
    "CHS457x16"
  ];
  const candSpec = candIds.map(id => "S690 " + id);
  const initialIndex = 17; // CHS219.1x8

  let calls = 0;
  function build(secsIn) {
    const members = defs.map((d, i) => [d[0], d[1], secsIn[i]]);
    return { note, nodes, members };
  }
  function run(secsIn) {
    if (calls >= 400) return null;
    calls++;
    try {
      return analyse(build(secsIn));
    } catch (e) {
      return null;
    }
  }
  function isGoodStrict(r) {
    if (!r || !r.ok) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.58) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sagLimit > 0) {
      if (r.sag > 0.80 * r.sagLimit) return false;
    }
    if (typeof r.frequency === "number" && typeof r.fMin === "number" && r.fMin > 0) {
      if (r.frequency < 1.12 * r.fMin) return false;
    }
    return true;
  }
  function isGoodLoose(r) {
    return !!(r && r.ok);
  }

  let secs = new Array(n).fill(candSpec[initialIndex]);
  let initialReport = run(secs);
  let useStrict = isGoodStrict(initialReport);

  if (!initialReport || !initialReport.ok) {
    // fallback to largest available section
    secs = new Array(n).fill(candSpec[candSpec.length - 1]);
    initialReport = run(secs);
    useStrict = isGoodStrict(initialReport);
    if (!initialReport || !initialReport.ok) {
      return build(secs);
    }
  }

  const okCond = useStrict ? isGoodStrict : isGoodLoose;

  function getXY(name) {
    if (name[0] === "D") {
      const i = parseInt(name.slice(1), 10);
      return [dx[i], 0];
    }
    if (name[0] === "T") {
      const i = parseInt(name.slice(1), 10);
      return [dx[i], yTop[i]];
    }
    if (name === "S1") return [0, -5.51];
    if (name === "S2") return [38.6, -5.51];
    return null;
  }

  const lengths = defs.map(d => {
    const p = getXY(d[0]);
    const q = getXY(d[1]);
    return Math.hypot(p[0] - q[0], p[1] - q[1]);
  });
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => lengths[b] - lengths[a]);

  let currentReport = initialReport;

  for (const i of order) {
    if (calls >= 385) break;
    const curSpec = secs[i];
    let hi = candSpec.indexOf(curSpec);
    if (hi < 0) hi = candSpec.length - 1;
    if (hi <= 0) continue;

    let best = hi;
    let bestReport = null;
    let l = 0;
    let h = hi;

    while (l <= h) {
      if (calls >= 395) break;
      const mid = Math.floor((l + h) / 2);
      const testSecs = secs.slice();
      testSecs[i] = candSpec[mid];
      const r = run(testSecs);
      if (okCond(r)) {
        best = mid;
        bestReport = r;
        h = mid - 1;
      } else {
        l = mid + 1;
      }
    }

    if (best !== hi) {
      secs[i] = candSpec[best];
      if (bestReport) currentReport = bestReport;
    }
  }

  const finalReport = run(secs);
  if (finalReport && finalReport.ok) {
    return build(secs);
  }

  // Conservative fallback
  const fallbackSecs = new Array(n).fill(candSpec[initialIndex]);
  const fallbackReport = run(fallbackSecs);
  if (fallbackReport && fallbackReport.ok) {
    return build(fallbackSecs);
  }
  const maxSecs = new Array(n).fill(candSpec[candSpec.length - 1]);
  return build(maxSecs);
}

