  const dx = [0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3, 22.057, 24.814, 27.571, 30.329, 33.086, 35.843, 38.6];
  const yTop = [2.5, 3.8, 5.0, 5.9, 6.5, 6.8, 6.9, 6.9, 6.8, 6.1, 2.0, 2.0, 2.1, 4.8, 3.0];

