    "CHS139.7x6.3",
    "CHS168.3x6.3",
    "CHS193.7x6.3",
    "CHS193.7x8",
    "CHS219.1x8",
    "CHS244.5x8",
    "CHS273x10",
    "CHS323.9x10",
    "CHS355.6x12.5",
    "CHS406.4x12.5",
    "CHS457x16"
  ];
  const cand = chs.map(function (id) { return "S690 " + id; });
  const maxIdx = cand.length - 1;

  let calls = 0;
  function buildWith(secs) {
    const members = [];
    for (let i = 0; i < defs.length; i++) {
      members.push([defs[i].a, defs[i].b, secs[i]]);
    }
    return { note: note, nodes: nodes, members: members };
  }
  function run(secs) {
    if (calls >= 392) return null;
    calls++;
    try {
      return analyse(buildWith(secs));
    } catch (e) {
      return null;
    }
  }

  function good(rr, strict) {
    if (!rr || !rr.ok) return false;
    const limU = strict ? 0.67 : 0.92;
    const limS = strict ? 0.68 : 0.94;
    const limF = strict ? 1.17 : 1.03;
    const limFat = strict ? 0.72 : 0.99;

    if (typeof rr.maxUtil === "number" && rr.maxUtil > limU) return false;
    if (typeof rr.sag === "number" && typeof rr.sagLimit === "number" && rr.sagLimit > 0) {
      if (rr.sag > limS * rr.sagLimit) return false;
    }
    if (typeof rr.frequency === "number" && typeof rr.fMin === "number" && rr.fMin > 0) {
      if (rr.frequency < limF * rr.fMin) return false;
    }
    if (typeof rr.fatigueWorst === "number" && rr.fatigueWorst > limFat) return false;
    return true;
  }

  let secs = new Array(defs.length).fill(cand[maxIdx]);
  let rInit = run(secs);

  // Fallback if the minimal support triangulation is somehow seen as a mechanism.
  if (!rInit || !rInit.ok) {
    add("S1", "D2", "sup");
    add("S2", "D12", "sup");
    secs = new Array(defs.length).fill(cand[maxIdx]);
    rInit = run(secs);
  }

  let safeSecs = null;
  let safeMass = Infinity;
  function record(rr, ss) {
    if (rr && good(rr, true)) {
      const m = (typeof rr.mass === "number") ? rr.mass : Infinity;
      if (m < safeMass) {
        safeMass = m;
        safeSecs = ss.slice();
      }
    }
  }
  record(rInit, secs);

  // Build group index sets from the current member list.
  const groups = {};
  for (let i = 0; i < defs.length; i++) {
    const t = defs[i].type;
    if (!groups[t]) groups[t] = [];
    groups[t].push(i);
  }

  // Coarse group sizing, diagonals first because they control global stiffness.
  const groupOrder = ["diag", "vert", "tc", "bc", "sup"];
  for (let gi = 0; gi < groupOrder.length; gi++) {
    const type = groupOrder[gi];
    const inds = groups[type];
    if (!inds || !inds.length) continue;

    let lo = 0;
    let hi = maxIdx;
    let best = maxIdx;
    while (lo <= hi) {
      if (calls >= 370) break;
      const mid = Math.floor((lo + hi) / 2);
      const test = secs.slice();
      for (let k = 0; k < inds.length; k++) {
        test[inds[k]] = cand[mid];
      }
      const rr = run(test);
      record(rr, test);
      if (good(rr, true)) {
        best = mid;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }
    if (best < maxIdx) {
      for (let k = 0; k < inds.length; k++) {
        secs[inds[k]] = cand[best];
      }
    }
  }

  // Per-member refinement. Two passes reduce local over-strength left by the uniform group pass.
  const priority = { diag: 0, vert: 1, tc: 2, bc: 3, sup: 4 };
  let order = [];
  for (let i = 0; i < defs.length; i++) order.push(i);
  order.sort(function (i, j) {
    const pi = priority[defs[i].type];
    const pj = priority[defs[j].type];
    if (pi !== pj) return pi - pj;
    return i - j;
  });

  for (let pass = 0; pass < 2; pass++) {
    if (calls >= 380) break;
    let changed = false;
    const localOrder = (pass % 2 === 0) ? order.slice() : order.slice().reverse();

    for (let oi = 0; oi < localOrder.length; oi++) {
      if (calls >= 380) break;
      const i = localOrder[oi];
      const cur = cand.indexOf(secs[i]);
      if (cur <= 0) continue;

      let lo = 0;
      let hi = cur;
      let best = cur;

      while (lo <= hi) {
        if (calls >= 380) break;
        const mid = Math.floor((lo + hi) / 2);
        const test = secs.slice();
        test[i] = cand[mid];
        const rr = run(test);
        record(rr, test);
        if (good(rr, true)) {
          best = mid;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (best < cur) {
        secs[i] = cand[best];
        changed = true;
      }
    }
    if (!changed) break;
  }

  // Return the lightest strictly acceptable design found; otherwise use the maximum sections.
  if (safeSecs) return buildWith(safeSecs);

  const fallback = new Array(defs.length).fill(cand[maxIdx]);
  return buildWith(fallback);
}

