    { U: 0.82, sag: 0.86, freq: 1.045, fat: 0.80 },
    { U: 0.89, sag: 0.93, freq: 1.025, fat: 0.88 },
    { U: 0.96, sag: 0.98, freq: 1.01, fat: 0.96 },
    { U: 1.00, sag: 1.00, freq: 1.00, fat: 1.00 }
  ];

  function good(r, L) {
    if (!r || !r.ok || r.error) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > L.U) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sagLimit > 0) {
      if (r.sag > L.sag * r.sagLimit) return false;
    }
    if (typeof r.frequency === "number" && typeof r.fMin === "number" && r.fMin > 0) {
      if (r.frequency < L.freq * r.fMin) return false;
    }
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > L.fat) return false;
    return true;
  }

