      for (let k = 0; k < inds.length; k++) test[inds[k]] = cand[mid];
      const rr = run(test);
      if (good(rr, L)) {
        best = mid;
        bestSecs = test.slice();
        bestRep = rr;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }

    if (best < cur && bestSecs) {
      secs = bestSecs.slice();
      currentRep = bestRep;
      updateSafe(secs, currentRep);
    }
  }

  // Coordinates for length-based ordering
  const coord = {};
  for (let i = 0; i < 15; i++) coord["D" + i] = [dx[i], 0];
  coord["S1"] = [0, -5.51];
  coord["S2"] = [38.6, -5.51];
  for (let i = 0; i < nodes.length; i++) {
