  for (let i = 0; i < n; i++) {
    const pa = coord[defs[i].a];
    const pb = coord[defs[i].b];
    lengths[i] = Math.hypot(pa[0] - pb[0], pa[1] - pb[1]);
  }

  const prio = {
    sup: 0,
    diagT: 1,
    diagR: 2,
    diagC: 3,
    vertR: 4,
    vertC: 5,
    botR: 6,
    topR: 7,
    topC: 8,
    bc: 9
