  for (let i = 0; i < n; i++) order.push(i);
  order.sort(function (i, j) {
    const pi = prio[defs[i].type];
    const pj = prio[defs[j].type];
    if (pi !== pj) return pi - pj;
    return lengths[j] - lengths[i];
  });

  // Per-member refinement, repeated while improvements occur
  let changed = true;
  for (let pass = 0; pass < 3 && changed && calls < MAXCALLS; pass++) {
    changed = false;
    const ord = (pass % 2 === 0) ? order.slice() : order.slice().reverse();

    for (let oi = 0; oi < ord.length && calls < MAXCALLS; oi++) {
      const i = ord[oi];
      const cur = cand.indexOf(secs[i]);
      if (cur <= 0) continue;

      let lo = 0;
      let hi = cur - 1;
      let best = cur;
      let bestSecs = null;
      let bestRep = null;

      while (lo <= hi && calls < MAXCALLS) {
        const mid = Math.floor((lo + hi) / 2);
        const test = secs.slice();
        test[i] = cand[mid];
        const rr = run(test);
        if (good(rr, L)) {
          best = mid;
          bestSecs = test.slice();
          bestRep = rr;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (best < cur && bestSecs) {
        secs = bestSecs.slice();
        currentRep = bestRep;
        changed = true;
        updateSafe(secs, currentRep);
      }
    }
  }

  if (safeSecs) return build(safeSecs);
  return build(secs);
}

