    let bestSecs = secs.slice();
    let bestMass = (current && typeof current.mass === "number") ? current.mass : Infinity;

    const order = [];
    for (let i = 0; i < secs.length; i++) order.push(i);
    order.sort(function (i, j) {
      const ai = areas[secs[i]];
      const aj = areas[secs[j]];
      if (aj !== ai) return aj - ai;
