          }
        }

        if (best < cur) {
          secs[i] = best;
          if (bestR) current = bestR;
          changed = true;
          const m = (current && typeof current.mass === "number") ? current.mass : Infinity;
          if (m < bestMass - 1e-6) {
            bestMass = m;
            bestSecs = secs.slice();
          }
        }
      }

      if (!changed) break;
    }

    return { secs: bestSecs, mass: bestMass };
  }

  const levels = [
    { U: 0.82, sag: 0.92, freq: 1.08, fat: 0.82 },
    { U: 0.90, sag: 0.96, freq: 1.04, fat: 0.90 },
    { U: 1.00, sag: 1.00, freq: 1.00, fat: 1.00 }
  ];

