  function localReduce(idxStart, rStart, lim, maxPasses, budget) {
    const startCalls = calls;
    let idx = idxStart.slice();
    let r = rStart;
    let bestIdx = null;
    let bestR = null;
    let bestMass = Infinity;

    function consider(ii, rr) {
      if (ii && rr && rr.ok && valid(rr, lim) && typeof rr.mass === "number" && rr.mass < bestMass) {
        bestMass = rr.mass;
        bestIdx = ii.slice();
        bestR = rr;
      }
    }
    consider(idx, r);

    for (let pass=0; pass<maxPasses; pass++) {
      if (calls - startCalls >= budget || calls >= MAXCALLS-5) break;
      let changed = false;

      const order = [];
      for (let i=0;i<N;i++) order.push(i);
      order.sort(function(i,j) {
        return (areas[idx[j]] * lengths[j]) - (areas[idx[i]] * lengths[i]);
      });

      for (let oi=0; oi<order.length; oi++) {
        if (calls - startCalls >= budget || calls >= MAXCALLS-5) break;
        const i = order[oi];
        const cur = idx[i];
        if (cur <= 0) continue;

        let test = idx.slice();
        test[i] = cur - 1;
        let rr = call(test);

        if (rr && valid(rr, lim)) {
          let lo = 0, hi = cur - 1;
          let best = cur - 1;
          let bestRR = rr;

          while (lo <= hi && calls - startCalls < budget && calls < MAXCALLS-5) {
            const mid = (lo + hi) >> 1;
            if (mid >= cur) break;
            test = idx.slice();
            test[i] = mid;
            rr = call(test);
            if (rr && valid(rr, lim)) {
              best = mid;
              bestRR = rr;
              hi = mid - 1;
            } else {
              lo = mid + 1;
            }
          }

          if (best < cur) {
            idx[i] = best;
            r = bestRR;
            changed = true;
            consider(idx, r);
          }
        }
      }

      if (!changed) break;
    }

    if (!bestIdx) return {idx: idx, r: r, mass: (r && typeof r.mass === "number") ? r.mass : Infinity};
    return {idx: bestIdx, r: bestR, mass: bestMass};
  }

  function search(startIdx, startR, lim, budget) {
    const startCalls = calls;
    let localBest = {idx: null, r: null, mass: Infinity};

    function consider(ii, rr) {
      if (ii && rr && rr.ok && valid(rr, lim) && typeof rr.mass === "number" && rr.mass < localBest.mass) {
        localBest = {idx: ii.slice(), r: rr, mass: rr.mass};
      }
    }

    let idx = startIdx.slice();
    let r = startR;
    consider(idx, r);

    if (!valid(r, lim)) {
      const rep = repair(idx, r, lim, 18);
      idx = rep.idx;
      r = rep.r;
      consider(idx, r);
    }

    let lr = localReduce(idx, r, lim, 2, Math.max(20, Math.floor(budget * 0.42)));
    consider(lr.idx, lr.r);

    if (startR && startR.ok && calls - startCalls < budget - 10) {
      const target = Math.min(lim.U, lim.F) * 0.90;
      const seed = makeSeed(startIdx, startR, target);
      let rs = call(seed);
      const rep = repair(seed, rs, lim, 20);
      consider(rep.idx, rep.r);

      if (calls - startCalls < budget - 10) {
        const lr2 = localReduce(rep.idx, rep.r, lim, 3, Math.max(15, budget - (calls - startCalls) - 8));
        consider(lr2.idx, lr2.r);
      }
    }

    if (localBest.idx && calls - startCalls < budget - 12) {
      const target = Math.min(lim.U, lim.F) * 0.82;
      const seed2 = makeSeed(localBest.idx, localBest.r, target);
      let rs2 = call(seed2);
      const rep2 = repair(seed2, rs2, lim, 15);
      consider(rep2.idx, rep2.r);

      if (calls - startCalls < budget - 8) {
        const lr3 = localReduce(rep2.idx, rep2.r, lim, 2, Math.max(12, budget - (calls - startCalls) - 5));
        consider(lr3.idx, lr3.r);
      }
    }

    return localBest;
  }

  const rBase = call(baseIdx);
  if (!rBase || rBase.error) return baseline;

  const limA = {U:0.77, F:0.77, f:2.75, sagFrac:0.92};
  const limB = {U:0.79, F:0.79, f:2.70, sagFrac:0.95};

  const A = search(baseIdx, rBase, limA, 175);

  let BStartIdx = A.idx ? A.idx : baseIdx;
  let BStartR = A.r ? A.r : rBase;
  if (!valid(BStartR, limB)) {
    const repB = repair(BStartIdx, BStartR, limB, 12);
    BStartIdx = repB.idx;
    BStartR = repB.r;
  }

  const B = search(BStartIdx, BStartR, limB, 165);

  let finalA = A;
  if (!finalA.idx || typeof finalA.mass !== "number") {
    finalA = {idx: baseIdx, r: rBase, mass: (rBase && typeof rBase.mass === "number") ? rBase.mass : Infinity};
  }

  let final = finalA;
  if (B && B.idx && B.r && valid(B.r, limB) && typeof B.mass === "number") {
    const bm = B.r;
    const mu = (typeof bm.maxUtil === "number") ? bm.maxUtil : maxMemberUtil(bm);
    const fw = (typeof bm.fatigueWorst === "number") ? bm.fatigueWorst : 1;
    const fr = (typeof bm.frequency === "number") ? bm.frequency : 0;
    if (mu <= 0.785 && fw <= 0.785 && fr >= 2.70) {
      if (B.mass < finalA.mass * 0.985 || B.mass < 18623) {
        final = B;
      }
    }
  }

  if (final.idx && final.r && final.r.ok) {
    return makeDesign(final.idx);
  }
  return baseline;
}

