  const cands = [];
  for (const m of Object.keys(DEN)) {
    for (const s of CHS) {
      cands.push({ spec: m + " " + s[0], mass: DEN[m] * s[1] * 1e-4, fy: FY[m] });
    }
  }
  cands.sort((p, q) => (p.mass - q.mass) || (p.fy - q.fy));

  // deck node x positions (given) and top-node heights
  const DX = [0, 2.757, 5.514, 8.271, 11.029, 13.786, 16.543, 19.3, 22.057, 24.814, 27.571, 30.329, 33.086, 35.843, 38.6];
  const HT = [0, 3.5, 5.0, 6.0, 6.6, 6.95, 6.95, 6.95, 6.95, 2.5, 2.4, 2.4, 2.4, 3.0];

  const nodes = [];
  for (let i = 1; i <= 13; i++) {
    nodes.push({ id: "T" + i, x: DX[i], y: HT[i], joint: "pin" });
  }

  const G = { deck: [], top: [], vert: [], diag: [], strut: [], anchor: [] };
  for (let i = 0; i <= 13; i++) G.deck.push(["D" + i, "D" + (i + 1)]);
  for (let i = 1; i <= 12; i++) G.top.push(["T" + i, "T" + (i + 1)]);
  for (let i = 1; i <= 13; i++) G.vert.push(["D" + i, "T" + i]);
  G.diag.push(["D0", "T1"]);
  for (let i = 1; i <= 6; i++) G.diag.push(["T" + i, "D" + (i + 1)]);
  G.diag.push(["T8", "D7"]);
  for (let i = 8; i <= 12; i++) G.diag.push(["T" + (i + 1), "D" + i]);
  G.diag.push(["D14", "T13"]);
  G.strut.push(["S1", "D0"], ["S2", "D14"]);
  G.anchor.push(["S1", "D1"]);
  const groups = Object.keys(G);

  function build(cfg) {
    const members = [];
    for (const g of groups) {
      for (const e of G[g]) {
        members.push([e[0], e[1], cands[cfg[g]].spec]);
      }
    }
    return {
      note: "Pratt truss, all pinned, group-sized CHS",
      nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, joint: n.joint })),
      joints: {},
      members: members
    };
  }

  let calls = 0;
  let bestMass = Infinity;
  let bestDesign = null;
  const cache = {};

  function evalCfg(cfg) {
    const key = groups.map(g => cfg[g]).join(",");
    if (key in cache) return cache[key];
    let r = null;
    try {
      r = analyse(build(cfg));
    } catch (e) {
      r = null;
    }
    calls++;
    let ok = false;
    if (r && !r.error && r.ok === true && typeof r.maxUtil === "number" && r.maxUtil <= TARGET) {
      ok = true;
      if (typeof r.mass === "number" && r.mass < bestMass) {
        bestMass = r.mass;
        bestDesign = build(cfg);
      }
    }
    cache[key] = ok;
    return ok;
  }

  const cfg = {};
  for (const g of groups) cfg[g] = cands.length - 1;
  evalCfg(cfg);

  for (let round = 0; round < 3 && calls < 300; round++) {
    let changed = false;
    for (const g of groups) {
      let lo = 0, hi = cfg[g];
