        trial[g] = mid;
        if (evalCfg(trial)) hi = mid; else lo = mid + 1;
      }
      if (hi !== cfg[g]) changed = true;
      cfg[g] = hi;
    }
    if (!changed) break;
  }

  if (bestDesign) return bestDesign;
  return build(cfg);
}

