    const u = utilsOf(r);
    if (!u) return false;
    for (let i = 0; i < NM; i++) if (!(u[i] <= CAPJ[ix[i]])) return false;
    const f = freqOf(r);
    if (!(f >= FREQ_T)) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.95 * r.sagLimit) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > 0.9) return false;
    return true;
  };

  // ---- stage 1: reach a feasible design (grow where needed) ----
  let ix = MEM.map(() => idxOf("CHS193.7x8"));
  let cur = null;
  for (let it = 0; it < 40 && calls < MAX_CALLS && elapsed() < LIMIT_MS; it++) {
    const r = run(ix);
    if (!r || r.error) break;
    const u = utilsOf(r);
    if (!u) break;
    if (feasible(r, ix)) { cur = { ix: ix.slice(), u: u }; break; }
    const f = freqOf(r);
    const nx = ix.slice();
    for (let i = 0; i < NM; i++) {
      if (u[i] > CAPJ[ix[i]]) {
        let j = idxForArea(CAT[ix[i]][1] * u[i] / (0.9 * CAPJ[ix[i]]));
        if (j <= ix[i]) j = ix[i] + 1;
        nx[i] = Math.min(NC - 1, Math.max(nx[i], j));
      }
    }
    if (!(f >= FREQ_T)) {
      const fr = (isFinite(f) && f > 0) ? f : 1.0;
      const mult = Math.min(2.2, Math.max(1.1, Math.pow(FREQ_T / fr, 2) * 1.05));
      for (let i = 0; i < NM; i++) {
        let j = idxForArea(CAT[ix[i]][1] * mult);
        if (j <= ix[i]) j = ix[i] + 1;
        nx[i] = Math.min(NC - 1, Math.max(nx[i], j));
      }
    }
    if (nx.every((v, i) => v === ix[i])) break;
    ix = nx;
  }

  // ---- stage 2: shrink members while staying feasible (batched greedy) ----
  let best = cur ? { ix: cur.ix.slice() } : null;
  if (cur) {
    let ixc = cur.ix.slice();
    let u = cur.u.slice();
    const frozen = new Array(NM).fill(false);
    const single = new Array(NM).fill(false);
    let k = Math.max(1, Math.floor(NM / 3));
    while (calls < MAX_CALLS && elapsed() < LIMIT_MS) {
      const props = [];
      for (let i = 0; i < NM; i++) {
        if (frozen[i] || ixc[i] === 0) continue;
        let j = ixc[i];
        if (single[i]) {
          j = ixc[i] - 1;
        } else {
          const a = CAT[ixc[i]][1];
          for (let jj = 0; jj < ixc[i]; jj++) {
            if (u[i] * a / CAT[jj][1] <= 0.92 * CAPJ[jj]) { j = jj; break; }
          }
        }
        if (j < ixc[i]) props.push({ i: i, j: j, slack: u[i] / CAPJ[ixc[i]] });
      }
      if (props.length === 0) break;
      props.sort((p, q) => p.slack - q.slack);
      const sel = props.slice(0, Math.min(k, props.length));
      const trial = ixc.slice();
      for (const p of sel) trial[p.i] = p.j;
      const r = run(trial);
      if (feasible(r, trial)) {
        ixc = trial;
        u = utilsOf(r);
        best = { ix: ixc.slice() };
        k = Math.min(NM, k * 2);
      } else if (sel.length === 1) {
        const p = sel[0];
        if (!single[p.i] && p.j < ixc[p.i] - 1) single[p.i] = true;
        else frozen[p.i] = true;
      } else {
        k = Math.max(1, Math.floor(sel.length / 2));
      }
    }
  }

  const finalIx = best ? best.ix : ix;
  return build(finalIx);
}

function design(site, analyse) {
