  add("D10", "T10"); add("D11", "T11"); add("D12", "T12"); add("D13", "T13"); // verticals right
  add("D14", "T13"); add("D14", "S2");
  add("D11", "B11"); add("D12", "B12"); add("D13", "B13");        // lower verticals
  add("B11", "B12"); add("B12", "B13"); add("B13", "S2");         // lower chord
  add("D11", "B12"); add("D12", "B13"); add("D14", "B13");        // lower diagonals
