    if (!r || !Array.isArray(r.members)) return null;
    const u = new Array(NM).fill(NaN);
    const comp = new Array(NM).fill(false);
    for (const e of r.members) {
      const toks = String(e.id).split(/[^A-Za-z0-9]+/);
      for (let i = 0; i < NM; i++) {
        if (toks.includes(MEM[i][0]) && toks.includes(MEM[i][1])) {
          const v = Number(e.util);
          u[i] = isFinite(v) ? v : NaN;
          comp[i] = COMP_RE.test(String(e.mode || ""));
        }
      }
    }
    if (u.some(v => !isFinite(v))) {
      if (r.members.length !== NM) return null;
      for (let i = 0; i < NM; i++) {
        const v = Number(r.members[i].util);
        if (!isFinite(v)) return null;
        u[i] = v;
        comp[i] = COMP_RE.test(String(r.members[i].mode || ""));
      }
    }
    return { u: u, comp: comp };
  }

  const freqOf = r => (typeof r.frequency === "number" ? r.frequency
                     : (typeof r.fMin === "number" ? r.fMin : NaN));

  function effMax(ex) {
    let m = 0;
    for (let i = 0; i < NM; i++) {
      const v = ex.u[i] * (ex.comp[i] ? COMP_F : 1.0);
      if (v > m) m = v;
    }
    return m;
  }

  function feasible(r, ex) {
    if (!r || r.error || !r.ok || !ex) return false;
    if (!(r.maxUtil <= ACC_NOM)) return false;
    if (effMax(ex) > ACC_EFF) return false;
    const f = freqOf(r);
    if (!(f >= FREQ_T)) return false;
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FAT_T) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > SAG_F * r.sagLimit) return false;
    return true;
  }

  let calls = 0;
  let best = null;
  let last = null;
  const cache = new Map();

  function run(ix) {
    const key = ix.join(",");
    if (cache.has(key)) return cache.get(key);
    let r = null;
    try { r = analyse(build(ix)); } catch (e) { r = null; }
    calls++;
    const ex = extract(r);
    const isF = feasible(r, ex);
    const res = {
      ix: ix.slice(), r: r, ex: ex, feas: isF,
      mass: (r && typeof r.mass === "number") ? r.mass : Infinity
