      const req = A * Math.max(ue, 0.01) / TU;
      let j = firstAtLeast(req);
      if (j < cur[i] - 2) j = cur[i] - 2;   // limit shrink per iteration
      nix[i] = j;
    }
    return nix;
  }

  let ix = new Array(NM).fill(idxOf("CHS139.7x6.3"));
  let boost = 1.0;

  for (let it = 0; it < MAX_IT && calls < MAX_CALLS && elapsed() < TIME_LIMIT; it++) {
    const res = run(ix);
