    if (!r || r.error || !res.ex) break;

    // global stiffness / fatigue / sag / utilisation boosts when they fail
    const f = freqOf(r);
    if (!(f >= FREQ_T)) {
      const fr = (isFinite(f) && f > 0) ? f : 1.0;
      boost *= Math.min(1.5, Math.max(1.03, Math.pow(FREQ_T / fr, 2)));
    }
    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > FAT_T) {
      boost *= Math.min(1.5, r.fatigueWorst / FAT_T);
    }
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > SAG_F * r.sagLimit) {
      boost *= Math.min(1.5, Math.pow(r.sag / (SAG_F * r.sagLimit), 2));
    }
    if (typeof r.maxUtil === "number" && r.maxUtil > ACC_NOM) {
      boost *= Math.min(1.3, Math.max(1.0, r.maxUtil / SIZE_T));
    }

