      nix = resize(ix, res.ex, boost);
      guard++;
    }
    if (nix.every((v, i) => v === ix[i]) && res.feas) break;   // converged and feasible
    ix = nix;
  }

  const pick = best || last;
  if (!pick) return build(new Array(NM).fill(idxOf("CHS168.3x6.3")));
  return build(pick.ix);
}

